import { Response } from 'express';
import { AuthRequest } from '../middleware/auth';
import { emergencyService } from '../services/emergency.service';

export class EmergencyController {
  // ============================================
  // EMERGENCY CASE MANAGEMENT
  // ============================================

  async createEmergencyCase(req: AuthRequest, res: Response): Promise<void> {
    try {
      const caseData = {
        ...req.body,
        registeredById: req.user!.id,
      };

      const emergencyCase = await emergencyService.createEmergencyCase(caseData);

      res.status(201).json({
        success: true,
        data: emergencyCase,
        message: 'Emergency case created successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async updateEmergencyCase(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const emergencyCase = await emergencyService.updateEmergencyCase(id, req.body);

      res.json({
        success: true,
        data: emergencyCase,
        message: 'Emergency case updated successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async setDisposition(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const emergencyCase = await emergencyService.setDisposition(id, req.body);

      res.json({
        success: true,
        data: emergencyCase,
        message: 'Disposition set successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async convertToFullRegistration(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const patientData = {
        ...req.body,
        registeredById: req.user!.id,
      };

      const result = await emergencyService.convertToFullRegistration(id, patientData);

      res.json({
        success: true,
        data: result,
        message: 'Emergency case converted to full patient registration',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getActiveEmergencyCases(req: AuthRequest, res: Response): Promise<void> {
    try {
      const cases = await emergencyService.getActiveEmergencyCases();

      res.json({
        success: true,
        data: cases,
        count: cases.length,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getEmergencyCaseById(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const emergencyCase = await emergencyService.getEmergencyCaseById(id);

      if (!emergencyCase) {
        res.status(404).json({
          success: false,
          message: 'Emergency case not found',
        });
        return;
      }

      res.json({
        success: true,
        data: emergencyCase,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getEmergencyStatistics(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { dateFrom, dateTo } = req.query;

      const stats = await emergencyService.getEmergencyStatistics(
        dateFrom ? new Date(dateFrom as string) : undefined,
        dateTo ? new Date(dateTo as string) : undefined
      );

      res.json({
        success: true,
        data: stats,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }
}

export const emergencyController = new EmergencyController();
