import { Response } from 'express';
import { AuthRequest } from '../middleware/auth';
import { nurseService } from '../services/nurse.service';

export class NurseController {
  // ============================================
  // TRIAGE
  // ============================================

  async createTriage(req: AuthRequest, res: Response): Promise<void> {
    try {
      const triageData = {
        ...req.body,
        triageById: req.user!.id,
      };

      const triage = await nurseService.createTriageRecord(triageData);

      res.status(201).json({
        success: true,
        data: triage,
        message: 'Triage record created successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getTriageQueue(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { triageLevel, routedTo, date } = req.query;

      const queue = await nurseService.getTriageQueue({
        triageLevel: triageLevel as any,
        routedTo: routedTo as any,
        date: date ? new Date(date as string) : undefined,
      });

      res.json({
        success: true,
        data: queue,
        count: queue.length,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  // ============================================
  // VITAL SIGNS
  // ============================================

  async recordVitalSigns(req: AuthRequest, res: Response): Promise<void> {
    try {
      const vitalData = {
        ...req.body,
        recordedById: req.user!.id,
      };

      const vitals = await nurseService.recordVitalSigns(vitalData);

      res.status(201).json({
        success: true,
        data: vitals,
        message: 'Vital signs recorded successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getVitalSignsHistory(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { patientId } = req.params;
      const { visitId } = req.query;

      const history = await nurseService.getVitalSignsHistory(
        patientId,
        visitId as string | undefined
      );

      res.json({
        success: true,
        data: history,
        count: history.length,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  // ============================================
  // NURSING NOTES
  // ============================================

  async createNursingNote(req: AuthRequest, res: Response): Promise<void> {
    try {
      const noteData = {
        ...req.body,
        createdById: req.user!.id,
      };

      const note = await nurseService.createNursingNote(noteData);

      res.status(201).json({
        success: true,
        data: note,
        message: 'Nursing note created successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async updateNursingNote(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const note = await nurseService.updateNursingNote(id, req.body);

      res.json({
        success: true,
        data: note,
        message: 'Nursing note updated successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async lockNursingNote(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const note = await nurseService.lockNursingNote(id);

      res.json({
        success: true,
        data: note,
        message: 'Nursing note locked successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getNursingNotes(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { visitId } = req.params;
      const notes = await nurseService.getNursingNotes(visitId);

      res.json({
        success: true,
        data: notes,
        count: notes.length,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  // ============================================
  // INJECTION ROOM
  // ============================================

  async getInjectionQueue(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { status, date } = req.query;

      const queue = await nurseService.getInjectionQueue({
        status: status as string,
        date: date ? new Date(date as string) : undefined,
      });

      res.json({
        success: true,
        data: queue,
        count: queue.length,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async administerInjection(req: AuthRequest, res: Response): Promise<void> {
    try {
      const administrationData = {
        ...req.body,
        administeredById: req.user!.id,
      };

      const administration = await nurseService.administerInjection(administrationData);

      res.status(201).json({
        success: true,
        data: administration,
        message: 'Injection administered successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  // ============================================
  // OBSERVATION BOARD
  // ============================================

  async getObservationBoard(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { location } = req.query;

      const board = await nurseService.getObservationBoard(location as any);

      res.json({
        success: true,
        data: board,
        count: board.length,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }
}

export const nurseController = new NurseController();
