import { Response } from 'express';
import { AuthRequest } from '../middleware/auth';
import { PatientPortalService } from '../services/patientPortal.service';

const service = new PatientPortalService();

export const getPatientPortalDashboard = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const data = await service.getDashboard(req.user.id, {
      ipAddress: req.ip,
      userAgent: req.get('user-agent') || undefined,
    });
    res.json({ success: true, data });
  } catch (error: any) {
    res.status(400).json({
      success: false,
      error: error.message || 'Failed to load portal',
    });
  }
};
