import { Router } from 'express';
import { PatientController } from '../controllers/patient.controller';
import { authenticate, authorize } from '../middleware/auth';
import { validate } from '../middleware/validation';
import { z } from 'zod';

const router = Router();
const patientController = new PatientController();

// Validation schemas
const createPatientSchema = z.object({
  fullName: z.string().min(2, 'Full name is required'),
  sex: z.enum(['MALE', 'FEMALE']),
  dateOfBirth: z.string(),
  phone: z.string().optional(),
  address: z.string().optional(),
  kebele: z.string().optional(),
  wereda: z.string().optional(),
  photoUrl: z.string().optional(),
  medicalHistory: z.string().optional(),
  allergies: z.string().optional(),
  bloodType: z.string().optional(),
  emergencyContactName: z.string().optional(),
  emergencyContactPhone: z.string().optional(),
  
  // Enhanced medical history fields
  hasAllergies: z.boolean().optional(),
  allergyDetails: z.string().optional(),
  hasDiabetes: z.boolean().optional(),
  hasHypertension: z.boolean().optional(),
  hasAsthma: z.boolean().optional(),
  hasHeartDisease: z.boolean().optional(),
  hasKidneyDisease: z.boolean().optional(),
  hasEpilepsy: z.boolean().optional(),
  currentMedications: z.string().optional(),
  familyHistory: z.string().optional(),
  surgicalHistory: z.string().optional(),
  socialHistory: z.string().optional(),
  
  // Data integrity fields
  isIncomplete: z.boolean().optional(),
  incompleteReason: z.string().optional(),
});

const checkDuplicatesSchema = z.object({
  fullName: z.string().min(2, 'Full name is required'),
  dateOfBirth: z.string().optional(),
  phone: z.string().optional(),
});

const archivePatientSchema = z.object({
  reason: z.string().min(5, 'Archive reason must be at least 5 characters'),
});

// All routes require authentication
router.use(authenticate);

// Routes
router.post(
  '/',
  authorize('RECEPTIONIST', 'SUPER_ADMIN'),
  validate(createPatientSchema),
  patientController.createPatient.bind(patientController)
);

router.get('/', patientController.getPatients.bind(patientController));
router.get('/:id', patientController.getPatientById.bind(patientController));
router.get('/:id/history', patientController.getPatientHistory.bind(patientController));

// Patient medical data endpoints
router.get('/:patientId/visits', patientController.getPatientVisits.bind(patientController));
router.get('/:patientId/lab-results', patientController.getPatientLabResults.bind(patientController));
router.get('/:patientId/prescriptions', patientController.getPatientPrescriptions.bind(patientController));
router.get('/:patientId/vitals', patientController.getPatientVitals.bind(patientController));

router.put('/:id', patientController.updatePatient.bind(patientController));
router.delete(
  '/:id',
  authorize('RECEPTIONIST', 'SUPER_ADMIN'),
  patientController.deletePatient.bind(patientController)
);

// New enhanced endpoints
router.post(
  '/check-duplicates',
  authorize('RECEPTIONIST', 'SUPER_ADMIN'),
  validate(checkDuplicatesSchema),
  patientController.checkDuplicates.bind(patientController)
);

router.put(
  '/:id/archive',
  authorize('RECEPTIONIST', 'SUPER_ADMIN'),
  validate(archivePatientSchema),
  patientController.archivePatient.bind(patientController)
);

router.put(
  '/:id/restore',
  authorize('RECEPTIONIST', 'SUPER_ADMIN'),
  patientController.restorePatient.bind(patientController)
);

router.put(
  '/:id/complete-registration',
  authorize('RECEPTIONIST', 'SUPER_ADMIN'),
  patientController.completeRegistration.bind(patientController)
);

export default router;
