import prisma from '../config/database';
import { FinanceService } from './finance.service';

const financeService = new FinanceService();

export class UltrasoundService {
  async createUltrasoundOrder(data: {
    visitId: string;
    patientId: string;
    ultrasoundType: string;
    isFollowUp: boolean;
    clinicalIndication?: string;
    orderedById: string;
    scheduledDate?: string;
  }) {
    // Generate order number
    const count = await prisma.ultrasoundOrder.count();
    const orderNumber = `US-${new Date().getFullYear()}-${String(count + 1).padStart(5, '0')}`;

    // Calculate price based on follow-up status
    const price = data.isFollowUp ? 400.00 : 200.00;

    const order = await prisma.ultrasoundOrder.create({
      data: {
        orderNumber,
        visitId: data.visitId,
        patientId: data.patientId,
        ultrasoundType: data.ultrasoundType,
        isFollowUp: data.isFollowUp,
        price,
        clinicalIndication: data.clinicalIndication,
        orderedById: data.orderedById,
        status: 'SCHEDULED',
        scheduledDate: data.scheduledDate ? new Date(data.scheduledDate) : null,
      },
      include: {
        patient: {
          select: {
            cardNumber: true,
            fullName: true,
            sex: true,
            dateOfBirth: true,
            phone: true,
          },
        },
        orderedBy: {
          select: {
            fullName: true,
            department: true,
          },
        },
        visit: {
          select: {
            visitNumber: true,
            visitDate: true,
          },
        },
      },
    });

    await financeService.createSystemCharge({
      patientId: data.patientId,
      visitId: data.visitId,
      transactionType: 'ULTRASOUND_FEE',
      amount: price,
      description: `Ultrasound order ${order.orderNumber}`,
    });

    return order;
  }

  async getUltrasoundOrders(params: {
    page?: number;
    limit?: number;
    status?: string;
    patientId?: string;
    date?: string;
  }) {
    const page = params.page || 1;
    const limit = params.limit || 20;
    const skip = (page - 1) * limit;

    const where: any = {};

    if (params.status) {
      where.status = params.status;
    }

    if (params.patientId) {
      where.patientId = params.patientId;
    }

    if (params.date) {
      const startDate = new Date(params.date);
      const endDate = new Date(params.date);
      endDate.setHours(23, 59, 59, 999);
      where.scheduledDate = { gte: startDate, lte: endDate };
    }

    const [orders, total] = await Promise.all([
      prisma.ultrasoundOrder.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: 'desc' },
        include: {
          patient: {
            select: {
              cardNumber: true,
              fullName: true,
              sex: true,
              dateOfBirth: true,
            },
          },
          orderedBy: {
            select: {
              fullName: true,
            },
          },
        },
      }),
      prisma.ultrasoundOrder.count({ where }),
    ]);

    return {
      orders,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
      },
    };
  }

  async getUltrasoundOrderById(id: string) {
    const order = await prisma.ultrasoundOrder.findUnique({
      where: { id },
      include: {
        patient: true,
        visit: true,
        orderedBy: {
          select: {
            fullName: true,
            department: true,
            phone: true,
          },
        },
      },
    });

    if (!order) {
      throw new Error('Ultrasound order not found');
    }

    return order;
  }

  async updateUltrasoundStatus(id: string, status: string) {
    const order = await prisma.ultrasoundOrder.update({
      where: { id },
      data: {
        status: status as any,
        ...(status === 'COMPLETED' && { completedAt: new Date() }),
      },
      include: {
        patient: {
          select: {
            fullName: true,
            cardNumber: true,
          },
        },
      },
    });

    return order;
  }

  async addUltrasoundArtifact(
    orderId: string,
    uploadedById: string,
    data: { name: string; url: string; type?: string; notes?: string }
  ) {
    const artifact = await prisma.auditLog.create({
      data: {
        userId: uploadedById,
        action: 'ULTRASOUND_ARTIFACT_ADDED',
        resource: 'ultrasound_orders',
        resourceId: orderId,
        newValues: {
          name: data.name,
          url: data.url,
          type: data.type || 'REPORT_LINK',
          notes: data.notes || '',
        } as any,
      },
      include: {
        user: {
          select: {
            id: true,
            fullName: true,
            role: true,
          },
        },
      },
    });
    return artifact;
  }

  async getUltrasoundArtifacts(orderId: string) {
    const artifacts = await prisma.auditLog.findMany({
      where: {
        action: 'ULTRASOUND_ARTIFACT_ADDED',
        resource: 'ultrasound_orders',
        resourceId: orderId,
      },
      orderBy: { createdAt: 'desc' },
      include: {
        user: {
          select: {
            id: true,
            fullName: true,
            role: true,
          },
        },
      },
    });
    return artifacts;
  }

  async getScheduledUltrasounds(date?: string) {
    const targetDate = date ? new Date(date) : new Date();
    const startDate = new Date(targetDate.setHours(0, 0, 0, 0));
    const endDate = new Date(targetDate.setHours(23, 59, 59, 999));

    const orders = await prisma.ultrasoundOrder.findMany({
      where: {
        scheduledDate: {
          gte: startDate,
          lte: endDate,
        },
        status: {
          in: ['SCHEDULED', 'IN_PROGRESS'],
        },
      },
      orderBy: { scheduledDate: 'asc' },
      include: {
        patient: {
          select: {
            cardNumber: true,
            fullName: true,
            sex: true,
            dateOfBirth: true,
            phone: true,
          },
        },
        orderedBy: {
          select: {
            fullName: true,
          },
        },
      },
    });

    return orders;
  }
}
