import prisma from '../config/database';
import { hashPassword, comparePassword } from '../utils/bcrypt';
import crypto from 'crypto';
import fs from 'fs/promises';
import path from 'path';

export class UserService {
  async getProfile(userId: string) {
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        email: true,
        fullName: true,
        phone: true,
        role: true,
        department: true,
        employmentType: true,
        isActive: true,
        emailVerified: true,
        profilePhoto: true,
        createdAt: true,
        lastLogin: true,
      },
    });

    if (!user) {
      throw new Error('User not found');
    }

    return user;
  }

  async updateProfile(
    userId: string,
    data: {
      fullName?: string;
      phone?: string;
      department?: string;
    }
  ) {
    const updateData: any = {};

    if (data.fullName?.trim()) {
      updateData.fullName = data.fullName.trim();
    }

    if (data.phone !== undefined) {
      updateData.phone = data.phone?.trim() || null;
    }

    if (data.department !== undefined) {
      updateData.department = data.department?.trim() || null;
    }

    const user = await prisma.user.update({
      where: { id: userId },
      data: updateData,
      select: {
        id: true,
        email: true,
        fullName: true,
        phone: true,
        role: true,
        department: true,
        profilePhoto: true,
      },
    });

    return user;
  }

  async changePassword(userId: string, currentPassword: string, newPassword: string) {
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { passwordHash: true },
    });

    if (!user) {
      throw new Error('User not found');
    }

    const isValid = await comparePassword(currentPassword, user.passwordHash);
    if (!isValid) {
      throw new Error('Current password is incorrect');
    }

    const newPasswordHash = await hashPassword(newPassword);

    await prisma.user.update({
      where: { id: userId },
      data: { passwordHash: newPasswordHash },
    });

    // Log the password change
    await prisma.auditLog.create({
      data: {
        userId,
        action: 'PASSWORD_CHANGED',
        resource: 'users',
        resourceId: userId,
        newValues: { changedAt: new Date().toISOString() } as any,
      },
    });
  }

  async requestEmailChange(userId: string, newEmail: string, password: string) {
    // Verify password
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { email: true, passwordHash: true, fullName: true },
    });

    if (!user) {
      throw new Error('User not found');
    }

    const isValid = await comparePassword(password, user.passwordHash);
    if (!isValid) {
      throw new Error('Password is incorrect');
    }

    // Check if new email is already in use
    const existingUser = await prisma.user.findUnique({
      where: { email: newEmail.toLowerCase().trim() },
    });

    if (existingUser) {
      throw new Error('Email is already in use');
    }

    // Generate 6-digit OTP
    const otp = Math.floor(100000 + Math.random() * 900000).toString();
    const otpExpiry = new Date(Date.now() + 15 * 60 * 1000); // 15 minutes

    // Store the OTP
    await prisma.user.update({
      where: { id: userId },
      data: {
        emailVerificationToken: otp,
        verificationEmailSentAt: new Date(),
      },
    });

    // Store the new email in audit log
    await prisma.auditLog.create({
      data: {
        userId,
        action: 'EMAIL_CHANGE_REQUESTED',
        resource: 'users',
        resourceId: userId,
        oldValues: { currentEmail: user.email } as any,
        newValues: { 
          newEmail: newEmail.toLowerCase().trim(),
          otp,
          expiresAt: otpExpiry.toISOString()
        } as any,
      },
    });

    // Send OTP email to NEW email address
    const { EmailService } = await import('./email.service');
    const emailService = new EmailService();
    await emailService.sendEmailChangeOTP(
      newEmail.toLowerCase().trim(),
      user.fullName,
      otp
    );

    return { newEmail: newEmail.toLowerCase().trim() };
  }

  async confirmEmailChange(userId: string, otp: string) {
    // Find the user
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        email: true,
        fullName: true,
        emailVerificationToken: true,
        verificationEmailSentAt: true,
      },
    });

    if (!user) {
      throw new Error('User not found');
    }

    // Find the email change request in audit logs
    const emailChangeRequest = await prisma.auditLog.findFirst({
      where: {
        userId,
        action: 'EMAIL_CHANGE_REQUESTED',
      },
      orderBy: {
        createdAt: 'desc',
      },
    });

    if (!emailChangeRequest) {
      throw new Error('No email change request found');
    }

    // Check if OTP matches
    if (user.emailVerificationToken !== otp) {
      throw new Error('Invalid OTP code');
    }

    // Check if OTP is expired (15 minutes)
    const newValues = emailChangeRequest.newValues as any;
    const expiresAt = new Date(newValues.expiresAt);
    if (expiresAt < new Date()) {
      throw new Error('OTP has expired. Please request a new one.');
    }

    const newEmail = newValues.newEmail;
    const oldEmail = (emailChangeRequest.oldValues as any).currentEmail;

    // Check again if new email is still available
    const existingUser = await prisma.user.findUnique({
      where: { email: newEmail },
    });

    if (existingUser && existingUser.id !== userId) {
      throw new Error('Email is already in use');
    }

    // Update the email
    const updatedUser = await prisma.user.update({
      where: { id: userId },
      data: {
        email: newEmail,
        emailVerificationToken: null,
        verificationEmailSentAt: null,
        emailVerified: true,
        emailVerifiedAt: new Date(),
      },
      select: {
        id: true,
        email: true,
        fullName: true,
        role: true,
      },
    });

    // Log the successful email change
    await prisma.auditLog.create({
      data: {
        userId,
        action: 'EMAIL_CHANGED',
        resource: 'users',
        resourceId: userId,
        oldValues: { email: oldEmail } as any,
        newValues: { email: newEmail } as any,
      },
    });

    return updatedUser;
  }

  async uploadProfilePhoto(userId: string, file: Express.Multer.File) {
    const uploadsDir = process.env.UPLOAD_DIR || './uploads';
    const profilePhotosDir = path.join(uploadsDir, 'profile-photos');

    // Ensure directory exists
    await fs.mkdir(profilePhotosDir, { recursive: true });

    // Generate unique filename
    const ext = path.extname(file.originalname);
    const filename = `${userId}-${Date.now()}${ext}`;
    const filepath = path.join(profilePhotosDir, filename);

    // Save file
    await fs.writeFile(filepath, file.buffer);

    // Delete old photo if exists
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { profilePhoto: true },
    });

    if (user?.profilePhoto) {
      // Remove leading slash and convert to proper path
      const relativePath = user.profilePhoto.replace(/^\//, '').replace(/\//g, path.sep);
      const oldPath = path.join(uploadsDir, relativePath);
      await fs.unlink(oldPath).catch(() => {
        // Ignore if file doesn't exist
      });
    }

    // Update user record - store relative path that works with both static and API serving
    const photoUrl = `/uploads/profile-photos/${filename}`;
    await prisma.user.update({
      where: { id: userId },
      data: { profilePhoto: photoUrl },
    });

    console.log(`[uploadProfilePhoto] ✅ Photo uploaded: ${photoUrl}`);
    console.log(`[uploadProfilePhoto] File saved to: ${filepath}`);

    return photoUrl;
  }

  async deleteProfilePhoto(userId: string) {
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { profilePhoto: true },
    });

    if (!user?.profilePhoto) {
      return;
    }

    // Delete file - handle path separators correctly
    const uploadsDir = process.env.UPLOAD_DIR || './uploads';
    const relativePath = user.profilePhoto.replace(/^\//, '').replace(/\//g, path.sep);
    const filepath = path.join(uploadsDir, relativePath);
    await fs.unlink(filepath).catch(() => {
      // Ignore if file doesn't exist
    });

    // Update user record
    await prisma.user.update({
      where: { id: userId },
      data: { profilePhoto: null },
    });

    console.log(`[deleteProfilePhoto] ✅ Photo deleted for user ${userId}`);
  }
}
