import { Response } from 'express';
import { AuthRequest } from '../middleware/auth';
import { doctorService } from '../services/doctor.service';

export class DoctorController {
  // ============================================
  // DOCTOR ENCOUNTER
  // ============================================

  async createEncounter(req: AuthRequest, res: Response): Promise<void> {
    try {
      const encounterData = {
        ...req.body,
        doctorId: req.user!.id,
      };

      const encounter = await doctorService.createEncounter(encounterData);

      res.status(201).json({
        success: true,
        data: encounter,
        message: 'Encounter created successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async updateEncounter(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const encounter = await doctorService.updateEncounter(id, req.body);

      res.json({
        success: true,
        data: encounter,
        message: 'Encounter updated successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async completeEncounter(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const encounter = await doctorService.completeEncounter(id, req.body);

      res.json({
        success: true,
        data: encounter,
        message: 'Encounter completed successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getEncounterById(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const encounter = await doctorService.getEncounterById(id);

      if (!encounter) {
        res.status(404).json({
          success: false,
          message: 'Encounter not found',
        });
        return;
      }

      res.json({
        success: true,
        data: encounter,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  // ============================================
  // PATIENT CHART
  // ============================================

  async getPatientChart(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { patientId } = req.params;
      const chart = await doctorService.getPatientChart(patientId);

      if (!chart) {
        res.status(404).json({
          success: false,
          message: 'Patient not found',
        });
        return;
      }

      res.json({
        success: true,
        data: chart,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getDoctorQueue(req: AuthRequest, res: Response): Promise<void> {
    try {
      const doctorId = req.user!.id;
      const { date } = req.query;

      const queue = await doctorService.getDoctorQueue(
        doctorId,
        date ? new Date(date as string) : undefined
      );

      res.json({
        success: true,
        data: queue,
        count: queue.length,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  // ============================================
  // DASHBOARD
  // ============================================

  async getDashboardStats(req: AuthRequest, res: Response): Promise<void> {
    try {
      const doctorId = req.user!.id;
      const stats = await doctorService.getDashboardStats(doctorId);

      res.json({
        success: true,
        data: stats,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getRecentActivity(req: AuthRequest, res: Response): Promise<void> {
    try {
      const doctorId = req.user!.id;
      const { limit } = req.query;
      const activity = await doctorService.getRecentActivity(
        doctorId,
        limit ? parseInt(limit as string) : 10
      );

      res.json({
        success: true,
        data: activity,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getQueueStats(req: AuthRequest, res: Response): Promise<void> {
    try {
      const doctorId = req.user!.id;
      const stats = await doctorService.getQueueStats(doctorId);

      res.json({
        success: true,
        data: stats,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async startVisit(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { visitId } = req.params;
      const doctorId = req.user!.id;
      const visit = await doctorService.startVisit(visitId, doctorId);

      res.json({
        success: true,
        data: visit,
        message: 'Visit started successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  // ============================================
  // ORDERS
  // ============================================

  async createLabOrder(req: AuthRequest, res: Response): Promise<void> {
    try {
      console.log('=== Lab Order Request ===');
      console.log('Request body:', JSON.stringify(req.body, null, 2));
      console.log('User:', JSON.stringify(req.user, null, 2));
      
      const orderData = {
        patientId: req.body.patientId,
        testIds: req.body.testIds,
        priority: req.body.priority,
        clinicalNotes: req.body.clinicalNotes,
        visitId: req.body.visitId,
        orderedById: req.user!.id,
      };
      
      console.log('Order data being sent to service:', JSON.stringify(orderData, null, 2));

      const labOrder = await doctorService.createLabOrder(orderData);

      res.status(201).json({
        success: true,
        data: labOrder,
        message: 'Lab order created successfully',
      });
    } catch (error: any) {
      console.error('Lab order creation error:', error);
      res.status(400).json({
        success: false,
        message: error.message,
        error: error.message,
      });
    }
  }

  async createPrescription(req: AuthRequest, res: Response): Promise<void> {
    try {
      const prescriptionData = {
        ...req.body,
        doctorId: req.user!.id,
      };

      const prescription = await doctorService.createPrescription(prescriptionData);

      res.status(201).json({
        success: true,
        data: prescription,
        message: 'Prescription created successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async createInjectionOrder(req: AuthRequest, res: Response): Promise<void> {
    try {
      const orderData = {
        ...req.body,
        orderedById: req.user!.id,
      };

      const injectionOrder = await doctorService.createInjectionOrder(orderData);

      res.status(201).json({
        success: true,
        data: injectionOrder,
        message: 'Injection order created successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async createUltrasoundOrder(req: AuthRequest, res: Response): Promise<void> {
    try {
      const orderData = {
        ...req.body,
        orderedById: req.user!.id,
      };

      const ultrasoundOrder = await doctorService.createUltrasoundOrder(orderData);

      res.status(201).json({
        success: true,
        data: ultrasoundOrder,
        message: 'Ultrasound order created successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }
}

export const doctorController = new DoctorController();
