import { Response } from 'express';
import { PharmacyService } from '../services/pharmacy.service';
import { AuthRequest } from '../middleware/auth';

const pharmacyService = new PharmacyService();

// Drug Management
export const createDrug = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const drug = await pharmacyService.createDrug(req.body);
    res.status(201).json({
      success: true,
      message: 'Drug created successfully',
      data: drug,
    });
  } catch (error: any) {
    res.status(400).json({
      success: false,
      error: error.message,
    });
  }
};

export const getDrugs = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const { search, category, isActive, page, limit } = req.query;
    const result = await pharmacyService.getDrugs({
      search: search as string,
      category: category as string,
      isActive: isActive === 'true',
      page: page ? Number(page) : undefined,
      limit: limit ? Number(limit) : undefined,
    });

    res.json({
      success: true,
      data: result.drugs,
      ...(page || limit ? { pagination: result.pagination } : {}),
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      error: error.message,
    });
  }
};

// Stock Management
export const addStock = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const stock = await pharmacyService.addStock(req.body);
    res.status(201).json({
      success: true,
      message: 'Stock added successfully',
      data: stock,
    });
  } catch (error: any) {
    res.status(400).json({
      success: false,
      error: error.message,
    });
  }
};

export const getStock = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const { page, limit, search, status, lowStock } = req.query;
    const result = await pharmacyService.getStock({
      page: page ? Number(page) : undefined,
      limit: limit ? Number(limit) : undefined,
      search: search as string,
      status: status as string,
      lowStock: lowStock === 'true',
    });

    res.json({
      success: true,
      data: result,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      error: error.message,
    });
  }
};

