import { Router } from 'express';
import { AuthController } from '../controllers/auth.controller';
import { authenticate, authorize } from '../middleware/auth';
import { loginRateLimiter, registerRateLimiter } from '../middleware/rateLimiters';
import { validate } from '../middleware/validation';
import { z } from 'zod';

const router = Router();
const authController = new AuthController();

// Validation schemas
const registerSchema = z.object({
  email: z.string().email('Invalid email format'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
  fullName: z.string().min(2, 'Full name is required'),
  phone: z.string().optional(),
  role: z.enum(['SUPER_ADMIN', 'DOCTOR', 'NURSE', 'RECEPTIONIST', 'PHARMACIST', 'LAB_TECH', 'FINANCE', 'EMERGENCY', 'INJECTION_ROOM']),
  department: z.string().optional(),
  employmentType: z.enum(['FULL_TIME', 'PART_TIME']).optional(),
});

const registerPatientSchema = z.object({
  email: z.string().email('Invalid email format'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
  fullName: z.string().min(2, 'Full name is required'),
  cardNumber: z.string().min(3, 'Clinic card number is required'),
  dateOfBirth: z.string().min(8, 'Date of birth is required'),
});

const loginSchema = z.object({
  email: z.string().email('Invalid email format'),
  password: z.string().min(1, 'Password is required'),
});

// Routes (rate limits reduce brute-force and spam registrations)
router.post(
  '/register',
  registerRateLimiter,
  validate(registerSchema),
  authController.register.bind(authController)
);
router.post(
  '/register-patient',
  registerRateLimiter,
  validate(registerPatientSchema),
  authController.registerPatient.bind(authController)
);
router.post('/login', loginRateLimiter, validate(loginSchema), authController.login.bind(authController));
router.post('/logout', authenticate, authController.logout.bind(authController));
router.get('/me', authenticate, authController.me.bind(authController));
router.get('/verify-email', authController.verifyEmail.bind(authController));
router.get('/doctors', authenticate, authController.getDoctors.bind(authController));
router.post(
  '/switch-clinical',
  authenticate,
  authorize('SUPER_ADMIN'),
  authController.switchToClinical.bind(authController)
);
router.post(
  '/switch-admin',
  authenticate,
  authorize('DOCTOR'),
  authController.switchToAdmin.bind(authController)
);

export default router;
