import { Router } from 'express';
import { AppointmentController } from '../controllers/appointment.controller';
import { authenticate, authorize } from '../middleware/auth';
import { validate } from '../middleware/validation';
import { z } from 'zod';

const router = Router();
const appointmentController = new AppointmentController();

// Validation schemas
const createAppointmentSchema = z.object({
  patientId: z.string().uuid(),
  doctorId: z.string().uuid(),
  appointmentDate: z.string(),
  startTime: z.string(),
  endTime: z.string(),
  serviceType: z.enum(['OPD', 'ULTRASOUND', 'EMERGENCY', 'INJECTION']),
  reason: z.string().optional(),
  notes: z.string().optional(),
});

const cancelAppointmentSchema = z.object({
  reason: z.string().min(5, 'Cancellation reason must be at least 5 characters'),
});

const rescheduleAppointmentSchema = z.object({
  appointmentDate: z.string(),
  startTime: z.string(),
  endTime: z.string(),
});

// All routes require authentication
router.use(authenticate);

// Routes
router.post(
  '/',
  authorize('RECEPTIONIST', 'SUPER_ADMIN', 'DOCTOR'),
  validate(createAppointmentSchema),
  appointmentController.createAppointment.bind(appointmentController)
);

router.get('/', appointmentController.getAppointments.bind(appointmentController));

router.get('/:id', appointmentController.getAppointmentById.bind(appointmentController));

router.put(
  '/:id/check-in',
  authorize('RECEPTIONIST', 'SUPER_ADMIN'),
  appointmentController.checkInAppointment.bind(appointmentController)
);

router.put(
  '/:id/cancel',
  authorize('RECEPTIONIST', 'SUPER_ADMIN', 'DOCTOR'),
  validate(cancelAppointmentSchema),
  appointmentController.cancelAppointment.bind(appointmentController)
);

router.put(
  '/:id/reschedule',
  authorize('RECEPTIONIST', 'SUPER_ADMIN'),
  validate(rescheduleAppointmentSchema),
  appointmentController.rescheduleAppointment.bind(appointmentController)
);

router.put(
  '/:id/no-show',
  authorize('RECEPTIONIST', 'SUPER_ADMIN'),
  appointmentController.markNoShow.bind(appointmentController)
);

router.put(
  '/:id/uncheck-in',
  authorize('RECEPTIONIST', 'SUPER_ADMIN'),
  appointmentController.uncheckInAppointment.bind(appointmentController)
);

export default router;
