import { PrismaClient, EncounterStatus } from '@prisma/client';
import { notificationService } from './notification.service';

const prisma = new PrismaClient();

export class DoctorService {
  // ============================================
  // DOCTOR ENCOUNTER MANAGEMENT
  // ============================================

  async createEncounter(data: {
    visitId: string;
    patientId: string;
    doctorId: string;
    subjective?: string;
    objective?: string;
    assessment?: string;
    plan?: string;
    primaryDiagnosis?: string;
    icdCode?: string;
    secondaryDiagnoses?: string[];
  }) {
    return await prisma.doctorEncounter.create({
      data: {
        ...data,
        status: 'IN_PROGRESS',
      },
      include: {
        patient: {
          select: {
            id: true,
            fullName: true,
            cardNumber: true,
            sex: true,
            dateOfBirth: true,
            photoUrl: true,
            allergies: true,
            medicalHistory: true,
          },
        },
        doctor: {
          select: {
            id: true,
            fullName: true,
          },
        },
      },
    });
  }

  async updateEncounter(id: string, data: {
    subjective?: string;
    objective?: string;
    assessment?: string;
    plan?: string;
    primaryDiagnosis?: string;
    icdCode?: string;
    secondaryDiagnoses?: string[];
    historyOfPresentIllness?: string;
    physicalExamination?: string;
    differentialDiagnosis?: string;
    treatmentPlan?: string;
  }) {
    return await prisma.doctorEncounter.update({
      where: { id },
      data,
    });
  }

  async completeEncounter(id: string, data?: {
    followUpRequired?: boolean;
    followUpDate?: Date;
    followUpNotes?: string;
    isReferral?: boolean;
    referralTo?: string;
    referralReason?: string;
    referralNotes?: string;
  }) {
    const encounter = await prisma.doctorEncounter.update({
      where: { id },
      data: {
        ...data,
        status: data?.followUpRequired ? 'FOLLOW_UP_NEEDED' : 'COMPLETED',
        completedAt: new Date(),
      },
      include: {
        visit: true,
      },
    });

    // Update visit status
    await prisma.patientVisit.update({
      where: { id: encounter.visitId },
      data: { status: 'COMPLETED' },
    });

    // Create follow-up appointment if needed
    if (data?.followUpRequired && data?.followUpDate) {
      const appointmentNumber = `APT-${Date.now()}`;
      await prisma.appointment.create({
        data: {
          appointmentNumber,
          patientId: encounter.patientId,
          doctorId: encounter.doctorId,
          appointmentDate: data.followUpDate,
          startTime: data.followUpDate,
          endTime: new Date(data.followUpDate.getTime() + 30 * 60000), // 30 minutes
          serviceType: 'OPD',
          reason: data.followUpNotes || 'Follow-up visit',
          status: 'SCHEDULED',
        },
      });
    }

    return encounter;
  }

  async getEncounterById(id: string) {
    return await prisma.doctorEncounter.findUnique({
      where: { id },
      include: {
        patient: {
          select: {
            id: true,
            fullName: true,
            cardNumber: true,
            sex: true,
            dateOfBirth: true,
            photoUrl: true,
            allergies: true,
            medicalHistory: true,
            phone: true,
            address: true,
          },
        },
        visit: {
          include: {
            triageRecords: {
              orderBy: { triageAt: 'desc' },
              take: 1,
            },
            vitalSigns: {
              orderBy: { recordedAt: 'desc' },
              take: 1,
            },
            prescriptions: {
              include: {
                items: true,
              },
            },
            labOrders: {
              include: {
                items: true,
              },
            },
            ultrasoundOrders: true,
            injectionOrders: true,
          },
        },
        doctor: {
          select: {
            id: true,
            fullName: true,
          },
        },
      },
    });
  }

  // ============================================
  // PATIENT CHART & HISTORY
  // ============================================

  async getPatientChart(patientId: string) {
    const patient = await prisma.patient.findUnique({
      where: { id: patientId },
      include: {
        visits: {
          include: {
            assignedDoctor: {
              select: {
                id: true,
                fullName: true,
              },
            },
            doctorEncounters: {
              orderBy: { startedAt: 'desc' },
            },
            triageRecords: {
              orderBy: { triageAt: 'desc' },
            },
            vitalSigns: {
              orderBy: { recordedAt: 'desc' },
            },
            prescriptions: {
              include: {
                items: {
                  include: {
                    drug: true,
                  },
                },
                dispensedBy: {
                  select: {
                    id: true,
                    fullName: true,
                  },
                },
              },
            },
            labOrders: {
              include: {
                items: {
                  include: {
                    test: true,
                  },
                },
              },
            },
            ultrasoundOrders: true,
            injectionOrders: {
              include: {
                administrations: true,
              },
            },
          },
          orderBy: { visitDate: 'desc' },
        },
        sickLeaveCertificates: {
          orderBy: { issuedAt: 'desc' },
        },
        medicalCertificates: {
          orderBy: { issuedAt: 'desc' },
        },
      },
    });

    return patient;
  }

  async getDoctorQueue(doctorId: string, date?: Date) {
    const where: any = {
      assignedDoctorId: doctorId,
      status: {
        in: ['IN_QUEUE', 'IN_CONSULTATION'],
      },
    };

    if (date) {
      const startOfDay = new Date(date);
      startOfDay.setHours(0, 0, 0, 0);
      const endOfDay = new Date(date);
      endOfDay.setHours(23, 59, 59, 999);

      where.visitDate = {
        gte: startOfDay,
        lte: endOfDay,
      };
    }

    return await prisma.patientVisit.findMany({
      where,
      include: {
        patient: {
          select: {
            id: true,
            fullName: true,
            cardNumber: true,
            sex: true,
            dateOfBirth: true,
            photoUrl: true,
            allergies: true,
          },
        },
        triageRecords: {
          orderBy: { triageAt: 'desc' },
          take: 1,
        },
        vitalSigns: {
          orderBy: { recordedAt: 'desc' },
          take: 1,
        },
        doctorEncounters: {
          where: { status: 'IN_PROGRESS' },
        },
      },
      orderBy: [
        { triageLevel: 'asc' },
        { queuePosition: 'asc' },
        { visitDate: 'asc' },
      ],
    });
  }

  // ============================================
  // DASHBOARD STATS
  // ============================================

  async getDashboardStats(doctorId: string) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    // Get today's visits
    const todayVisits = await prisma.patientVisit.findMany({
      where: {
        assignedDoctorId: doctorId,
        visitDate: {
          gte: today,
          lt: tomorrow,
        },
      },
      include: {
        triageRecords: {
          orderBy: { triageAt: 'desc' },
          take: 1,
        },
        doctorEncounters: {
          where: {
            doctorId,
            startedAt: {
              gte: today,
            },
          },
        },
      },
    });

    // Count by status
    const patientsWaiting = todayVisits.filter(v => v.status === 'IN_QUEUE').length;
    const patientsInProgress = todayVisits.filter(v => v.status === 'IN_CONSULTATION').length;
    const patientsCompleted = todayVisits.filter(v => v.status === 'COMPLETED').length;

    // Count critical patients
    const criticalPatients = todayVisits.filter(
      v => v.triageLevel === 'CRITICAL' && v.status !== 'COMPLETED'
    ).length;

    // Get pending lab results
    const pendingLabResults = await prisma.labOrder.count({
      where: {
        orderedById: doctorId,
        status: {
          in: ['IN_PROGRESS', 'PENDING'],
        },
      },
    });

    // Get pending prescriptions
    const pendingPrescriptions = await prisma.prescription.count({
      where: {
        doctorId,
        status: 'PENDING',
      },
    });

    // Get today's appointments
    const todayAppointments = await prisma.appointment.count({
      where: {
        doctorId,
        appointmentDate: {
          gte: today,
          lt: tomorrow,
        },
        status: {
          in: ['SCHEDULED', 'CONFIRMED'],
        },
      },
    });

    // Calculate average consultation time
    const completedEncounters = todayVisits
      .flatMap(v => v.doctorEncounters)
      .filter(e => e.completedAt);

    let averageConsultationTime = 0;
    if (completedEncounters.length > 0) {
      const totalMinutes = completedEncounters.reduce((sum, encounter) => {
        const duration = encounter.completedAt!.getTime() - encounter.startedAt.getTime();
        return sum + duration / 60000; // Convert to minutes
      }, 0);
      averageConsultationTime = Math.round(totalMinutes / completedEncounters.length);
    }

    return {
      patientsWaiting,
      patientsInProgress,
      patientsCompleted,
      criticalPatients,
      pendingLabResults,
      pendingPrescriptions,
      todayAppointments,
      averageConsultationTime,
    };
  }

  async getRecentActivity(doctorId: string, limit = 10) {
    const activities: any[] = [];

    // Get recent encounters
    const recentEncounters = await prisma.doctorEncounter.findMany({
      where: { doctorId },
      include: {
        patient: {
          select: {
            fullName: true,
          },
        },
      },
      orderBy: { startedAt: 'desc' },
      take: 5,
    });

    for (const encounter of recentEncounters) {
      activities.push({
        id: encounter.id,
        type: 'CONSULTATION',
        patientName: encounter.patient.fullName,
        description: `Consultation ${encounter.status === 'COMPLETED' ? 'completed' : 'in progress'}`,
        timestamp: encounter.startedAt.toISOString(),
        priority: 'NORMAL',
      });
    }

    // Get recent lab results
    const recentLabResults = await prisma.labOrder.findMany({
      where: {
        orderedById: doctorId,
        status: 'COMPLETED',
      },
      include: {
        patient: {
          select: {
            fullName: true,
          },
        },
      },
      orderBy: { updatedAt: 'desc' },
      take: 5,
    });

    for (const lab of recentLabResults) {
      activities.push({
        id: lab.id,
        type: 'LAB_RESULT',
        patientName: lab.patient.fullName,
        description: 'Lab results available',
        timestamp: lab.updatedAt.toISOString(),
        priority: 'NORMAL',
      });
    }

    // Get critical alerts (patients with critical triage)
    const criticalPatients = await prisma.patientVisit.findMany({
      where: {
        assignedDoctorId: doctorId,
        triageLevel: 'CRITICAL',
        status: {
          in: ['IN_QUEUE', 'IN_CONSULTATION'],
        },
      },
      include: {
        patient: {
          select: {
            fullName: true,
          },
        },
      },
      orderBy: { visitDate: 'desc' },
      take: 3,
    });

    for (const visit of criticalPatients) {
      activities.push({
        id: visit.id,
        type: 'CRITICAL_ALERT',
        patientName: visit.patient.fullName,
        description: 'Critical patient requires immediate attention',
        timestamp: visit.visitDate.toISOString(),
        priority: 'HIGH',
      });
    }

    // Sort by timestamp and limit
    return activities
      .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
      .slice(0, limit);
  }

  async getQueueStats(doctorId: string) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    const todayVisits = await prisma.patientVisit.findMany({
      where: {
        assignedDoctorId: doctorId,
        visitDate: {
          gte: today,
          lt: tomorrow,
        },
      },
      include: {
        doctorEncounters: {
          where: {
            doctorId,
            startedAt: {
              gte: today,
            },
          },
        },
      },
    });

    const waiting = todayVisits.filter(v => v.status === 'IN_QUEUE').length;
    const inProgress = todayVisits.filter(v => v.status === 'IN_CONSULTATION').length;
    const completed = todayVisits.filter(v => v.status === 'COMPLETED').length;

    // Calculate average wait time for waiting patients
    const waitingVisits = todayVisits.filter(v => v.status === 'IN_QUEUE');
    let averageWaitTime = 0;
    if (waitingVisits.length > 0) {
      const now = new Date();
      const totalWaitMinutes = waitingVisits.reduce((sum, visit) => {
        const waitTime = now.getTime() - visit.visitDate.getTime();
        return sum + waitTime / 60000; // Convert to minutes
      }, 0);
      averageWaitTime = Math.round(totalWaitMinutes / waitingVisits.length);
    }

    return {
      waiting,
      inProgress,
      completed,
      averageWaitTime,
    };
  }

  async startVisit(visitId: string, doctorId: string) {
    // Update visit status
    const visit = await prisma.patientVisit.update({
      where: { id: visitId },
      data: { status: 'IN_CONSULTATION' },
      include: {
        patient: true,
      },
    });

    // Create encounter if not exists
    const existingEncounter = await prisma.doctorEncounter.findFirst({
      where: {
        visitId,
        doctorId,
      },
    });

    if (!existingEncounter) {
      await prisma.doctorEncounter.create({
        data: {
          visitId,
          patientId: visit.patientId,
          doctorId,
          status: 'IN_PROGRESS',
        },
      });
    }

    return visit;
  }

  // ============================================
  // ORDER MANAGEMENT
  // ============================================

  async createLabOrder(data: {
    visitId?: string;
    patientId: string;
    orderedById: string;
    testIds: string[];
    priority?: 'STAT' | 'URGENT' | 'ROUTINE';
    clinicalNotes?: string;
  }) {
    const orderNumber = `LAB-${Date.now()}`;

    // Get test details
    const tests = await prisma.labTest.findMany({
      where: {
        id: {
          in: data.testIds,
        },
      },
    });

    const labOrder = await prisma.labOrder.create({
      data: {
        orderNumber,
        visitId: data.visitId || null,
        patientId: data.patientId,
        orderedById: data.orderedById,
        priority: data.priority || 'ROUTINE',
        clinicalNotes: data.clinicalNotes,
        status: 'PENDING',
        items: {
          create: tests.map(test => ({
            testId: test.id,
            testName: test.testName,
            status: 'PENDING',
          })),
        },
      },
      include: {
        items: {
          include: {
            test: true,
          },
        },
        patient: {
          select: {
            id: true,
            fullName: true,
            cardNumber: true,
          },
        },
      },
    });

    // Create financial transactions for each test
    for (const test of tests) {
      if (test.price) {
        await prisma.financialTransaction.create({
          data: {
            transactionNumber: `LAB-${Date.now()}-${test.id}`,
            patientId: data.patientId,
            visitId: data.visitId || null,
            transactionType: 'LAB_TEST',
            amount: test.price,
            paymentMethod: 'CASH',
            paymentStatus: 'PENDING',
            description: `Lab Test: ${test.testName}`,
          },
        });
      }
    }

    // Notify lab technicians
    const labTechs = await prisma.user.findMany({
      where: {
        role: 'LAB_TECH',
        isActive: true,
      },
    });

    for (const tech of labTechs) {
      await prisma.notification.create({
        data: {
          userId: tech.id,
          notificationType: 'NEW_LAB_ORDER',
          title: 'New Lab Order',
          message: `New lab order for ${labOrder.patient.fullName} - ${tests.length} test(s)`,
          relatedId: labOrder.id,
        },
      });
    }

    return labOrder;
  }

  async createPrescription(data: {
    visitId: string;
    patientId: string;
    doctorId: string;
    notes?: string;
    items: Array<{
      drugId?: string;
      drugName: string;
      dosage: string;
      frequency: string;
      duration: string;
      quantity: number;
      instructions?: string;
    }>;
  }) {
    const prescriptionNumber = `RX-${Date.now()}`;

    const prescription = await prisma.prescription.create({
      data: {
        prescriptionNumber,
        visitId: data.visitId,
        patientId: data.patientId,
        doctorId: data.doctorId,
        notes: data.notes,
        status: 'PENDING',
        items: {
          create: data.items,
        },
      },
      include: {
        items: {
          include: {
            drug: true,
          },
        },
        patient: {
          select: {
            id: true,
            fullName: true,
            cardNumber: true,
          },
        },
      },
    });

    // Notify pharmacists
    const pharmacists = await prisma.user.findMany({
      where: {
        role: 'PHARMACIST',
        isActive: true,
      },
    });

    for (const pharmacist of pharmacists) {
      await prisma.notification.create({
        data: {
          userId: pharmacist.id,
          notificationType: 'NEW_PRESCRIPTION',
          title: 'New Prescription',
          message: `New prescription for ${prescription.patient.fullName} - ${data.items.length} medication(s)`,
          relatedId: prescription.id,
        },
      });
    }

    return prescription;
  }

  async createInjectionOrder(data: {
    visitId: string;
    patientId: string;
    orderedById: string;
    medicationName: string;
    dosage: string;
    route: string;
    frequency?: string;
    duration?: string;
  }) {
    const orderNumber = `INJ-${Date.now()}`;

    const injectionOrder = await prisma.injectionOrder.create({
      data: {
        ...data,
        orderNumber,
        status: 'PENDING',
      },
      include: {
        patient: {
          select: {
            id: true,
            fullName: true,
            cardNumber: true,
          },
        },
      },
    });

    // Notify injection room nurses
    const nurses = await prisma.user.findMany({
      where: {
        role: {
          in: ['NURSE', 'INJECTION_ROOM'],
        },
        isActive: true,
      },
    });

    for (const nurse of nurses) {
      await prisma.notification.create({
        data: {
          userId: nurse.id,
          notificationType: 'NEW_INJECTION_ORDER',
          title: 'New Injection Order',
          message: `New injection order for ${injectionOrder.patient.fullName} - ${data.medicationName}`,
          relatedId: injectionOrder.id,
        },
      });
    }

    return injectionOrder;
  }

  async createUltrasoundOrder(data: {
    visitId: string;
    patientId: string;
    orderedById: string;
    ultrasoundType: string;
    isFollowUp: boolean;
    clinicalIndication?: string;
    scheduledDate?: Date;
  }) {
    const orderNumber = `US-${Date.now()}`;
    const price = data.isFollowUp ? 400 : 200; // Follow-up: 400 ETB, One-time: 200 ETB

    const ultrasoundOrder = await prisma.ultrasoundOrder.create({
      data: {
        ...data,
        orderNumber,
        price,
        status: 'SCHEDULED',
      },
      include: {
        patient: {
          select: {
            id: true,
            fullName: true,
            cardNumber: true,
          },
        },
      },
    });

    // Create financial transaction
    await prisma.financialTransaction.create({
      data: {
        transactionNumber: `US-${Date.now()}`,
        patientId: data.patientId,
        visitId: data.visitId,
        transactionType: 'ULTRASOUND',
        amount: price,
        paymentMethod: 'CASH',
        paymentStatus: 'PENDING',
        description: `Ultrasound: ${data.ultrasoundType}`,
      },
    });

    return ultrasoundOrder;
  }
}

export const doctorService = new DoctorService();
