import { Router } from 'express';
import { certificateController } from '../controllers/certificate.controller';
import { authenticate, authorize } from '../middleware/auth';

const router = Router();

// All routes require authentication
router.use(authenticate);

// Certificate routes require DOCTOR role
const doctorRoles = ['DOCTOR', 'SUPER_ADMIN'];

// ============================================
// SICK LEAVE CERTIFICATE ROUTES
// ============================================

// Create sick leave certificate
router.post(
  '/sick-leave',
  authorize(doctorRoles),
  (req, res) => certificateController.createSickLeaveCertificate(req, res)
);

// Get sick leave certificate by ID
router.get(
  '/sick-leave/:id',
  authorize([...doctorRoles, 'RECEPTIONIST', 'FINANCE']),
  (req, res) => certificateController.getSickLeaveCertificate(req, res)
);

// Get patient's sick leave certificates
router.get(
  '/sick-leave/patient/:patientId',
  authorize([...doctorRoles, 'RECEPTIONIST']),
  (req, res) => certificateController.getPatientSickLeaveCertificates(req, res)
);

// ============================================
// MEDICAL CERTIFICATE ROUTES
// ============================================

// Create medical certificate
router.post(
  '/medical',
  authorize(doctorRoles),
  (req, res) => certificateController.createMedicalCertificate(req, res)
);

// Update medical certificate
router.put(
  '/medical/:id',
  authorize(doctorRoles),
  (req, res) => certificateController.updateMedicalCertificate(req, res)
);

// Sign medical certificate
router.post(
  '/medical/:id/sign',
  authorize(doctorRoles),
  (req, res) => certificateController.signMedicalCertificate(req, res)
);

// Get medical certificate by ID
router.get(
  '/medical/:id',
  authorize([...doctorRoles, 'RECEPTIONIST', 'FINANCE']),
  (req, res) => certificateController.getMedicalCertificate(req, res)
);

// Get patient's medical certificates
router.get(
  '/medical/patient/:patientId',
  authorize([...doctorRoles, 'RECEPTIONIST']),
  (req, res) => certificateController.getPatientMedicalCertificates(req, res)
);

export default router;
