// Reports
export const getRevenueReport = async (req: Request, res: Response) => {
  try {
    const { startDate, endDate } = req.query;
    
    if (!startDate || !endDate) {
      res.status(400).json({
        success: false,
        error: 'Start date and end date are required',
      });
      return;
    }

    const report = await financeService.getRevenueReport(
      startDate as string,
      endDate as string
    );

    res.json({
      success: true,
      data: report,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      error: error.message || 'Failed to generate revenue report',
    });
  }
};

export const getDailyRevenue = async (req: Request, res: Response) => {
  try {
    const { date } = req.query;
    const userRole = req.user?.role;

    let report;
    
    // Role-based revenue filtering
    if (userRole === 'RECEPTIONIST') {
      // Reception sees only card fees and ultrasound fees
      report = await financeService.getReceptionDailyRevenue(date as string);
    } else if (userRole === 'SUPER_ADMIN') {
      // Super admin sees everything (all finance cases including reception)
      report = await financeService.getDailyRevenue(date as string);
    } else if (userRole === 'FINANCE') {
      // Finance sees everything EXCEPT card fees and ultrasound fees
      report = await financeService.getFinanceDailyRevenue(date as string);
    } else if (userRole === 'PHARMACIST') {
      // Pharmacy sees only pharmacy sales
      report = await financeService.getPharmacyDailyRevenue(date as string);
    } else {
      // Default: show all
      report = await financeService.getDailyRevenue(date as string);
    }

    res.json({
      success: true,
      data: report,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      error: error.message || 'Failed to get daily revenue',
    });
  }
};

