import { Router } from 'express';
import { VisitController } from '../controllers/visit.controller';
import { authenticate, authorize } from '../middleware/auth';
import { validate } from '../middleware/validation';
import { z } from 'zod';

const router = Router();
const visitController = new VisitController();

// Validation schemas
const createVisitSchema = z.object({
  patientId: z.string().uuid(),
  visitType: z.enum(['NEW', 'REPEAT', 'FOLLOW_UP']),
  serviceType: z.enum(['OPD', 'ULTRASOUND', 'EMERGENCY', 'INJECTION']),
  assignedDoctorId: z.string().uuid().optional(),
});

const updateStatusSchema = z.object({
  status: z.enum(['REGISTERED', 'IN_QUEUE', 'IN_CONSULTATION', 'COMPLETED']),
});

const assignDoctorSchema = z.object({
  doctorId: z.string().uuid(),
});

const saveSoapSchema = z.object({
  patientId: z.string().uuid(),
  chiefComplaint: z.string().min(3),
  subjective: z.string().min(10),
  objective: z.string().min(10),
  assessment: z.string().min(10),
  plan: z.string().min(10),
  vitalSigns: z
    .object({
      bloodPressure: z.string().optional(),
      temperature: z.string().optional(),
      heartRate: z.string().optional(),
      respiratoryRate: z.string().optional(),
      oxygenSaturation: z.string().optional(),
    })
    .optional(),
  isDraft: z.boolean().optional(),
});

const nurseVitalsSchema = z.object({
  bloodPressureSystolic: z.number().min(50).max(250),
  bloodPressureDiastolic: z.number().min(30).max(150),
  temperature: z.number().min(35).max(42),
  heartRate: z.number().min(40).max(200),
  respiratoryRate: z.number().min(8).max(40),
  oxygenSaturation: z.number().min(70).max(100),
  weight: z.number().min(1).max(300).optional(),
  height: z.number().min(50).max(250).optional(),
  bmi: z.number().optional(),
  notes: z.string().optional(),
});

// All routes require authentication
router.use(authenticate);

// Routes
router.post(
  '/',
  authorize('RECEPTIONIST', 'SUPER_ADMIN', 'NURSE'),
  validate(createVisitSchema),
  visitController.createVisit.bind(visitController)
);

router.get('/', visitController.getVisits.bind(visitController));

router.post(
  '/:id/nurse-vitals',
  authorize('NURSE', 'SUPER_ADMIN'),
  validate(nurseVitalsSchema),
  visitController.recordNurseVitals.bind(visitController)
);

router.get('/:id', visitController.getVisitById.bind(visitController));

router.patch(
  '/:id/status',
  validate(updateStatusSchema),
  visitController.updateVisitStatus.bind(visitController)
);

router.patch(
  '/:id/assign-doctor',
  authorize('RECEPTIONIST', 'SUPER_ADMIN'),
  validate(assignDoctorSchema),
  visitController.assignDoctor.bind(visitController)
);

router.post(
  '/:id/soap',
  authorize('DOCTOR', 'SUPER_ADMIN'),
  validate(saveSoapSchema),
  visitController.saveSoapNote.bind(visitController)
);

router.get(
  '/:id/timeline',
  authorize('DOCTOR', 'NURSE', 'SUPER_ADMIN'),
  visitController.getEncounterTimeline.bind(visitController)
);

export default router;
