import { UserRole } from '@prisma/client';
import prisma from '../config/database';

export class ChatService {
  async getPeerSummary(userId: string) {
    return prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        fullName: true,
        role: true,
        department: true,
        email: true,
        profilePhoto: true,
      },
    });
  }

  async listChatUsers(currentUserId: string) {
    return prisma.user.findMany({
      where: {
        id: { not: currentUserId },
        isActive: true,
        isApproved: true,
        role: { not: UserRole.PATIENT },
      },
      select: {
        id: true,
        fullName: true,
        role: true,
        department: true,
        profilePhoto: true,
      },
      orderBy: { fullName: 'asc' },
    });
  }

  async getConversation(currentUserId: string, withUserId: string) {
    const rows = await prisma.notification.findMany({
      where: {
        userId: currentUserId,
        notificationType: 'CHAT_DM',
        relatedId: withUserId,
      },
      orderBy: { createdAt: 'asc' },
      take: 200,
    });

    return rows.map((row) => {
      let senderId = '';
      let senderName = 'Unknown';
      if (row.title.startsWith('FROM:')) {
        const rest = row.title.slice(5);
        const pipe = rest.indexOf('|');
        if (pipe >= 0) {
          senderId = rest.slice(0, pipe);
          senderName = rest.slice(pipe + 1).trim() || 'Unknown';
        } else {
          senderId = rest;
        }
      }
      return {
        id: row.id,
        senderId,
        senderName,
        message: row.message,
        createdAt: row.createdAt,
        isOwn: senderId === currentUserId,
      };
    });
  }

  async sendMessage(senderId: string, recipientId: string, message: string) {
    const sender = await prisma.user.findUnique({
      where: { id: senderId },
      select: { fullName: true },
    });
    if (!sender) {
      throw new Error('Sender not found');
    }

    const payloadTitle = `FROM:${senderId}|${sender.fullName}`;

    const [recipientMessage, senderCopy] = await prisma.$transaction([
      prisma.notification.create({
        data: {
          userId: recipientId,
          notificationType: 'CHAT_DM',
          title: payloadTitle,
          message,
          relatedId: senderId,
          isRead: false,
        },
      }),
      prisma.notification.create({
        data: {
          userId: senderId,
          notificationType: 'CHAT_DM',
          title: payloadTitle,
          message,
          relatedId: recipientId,
          isRead: true,
          readAt: new Date(),
        },
      }),
    ]);

    return { recipientMessage, senderCopy };
  }
}
