import { Response } from 'express';
import { VisitService } from '../services/visit.service';
import { AuthRequest } from '../middleware/auth';

const visitService = new VisitService();

export class VisitController {
  async createVisit(req: AuthRequest, res: Response): Promise<void> {
    try {
      const visit = await visitService.createVisit({
        ...req.body,
        registeredById: req.user.id,
      });

      res.status(201).json({
        success: true,
        message: 'Visit created successfully',
        data: visit,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async getVisits(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { page, limit, date, status, doctorId, serviceType, unassignedOnly } = req.query;

      const result = await visitService.getVisits({
        page: page ? Number(page) : undefined,
        limit: limit ? Number(limit) : undefined,
        date: date as string,
        status: status as string,
        doctorId: doctorId as string,
        serviceType: serviceType as string,
        unassignedOnly: unassignedOnly === 'true' || unassignedOnly === '1',
      });

      res.json({
        success: true,
        data: result,
      });
    } catch (error: any) {
      res.status(500).json({
        success: false,
        error: error.message,
      });
    }
  }

  async getVisitById(req: AuthRequest, res: Response): Promise<void> {
    try {
      const visit = await visitService.getVisitById(req.params.id);

      res.json({
        success: true,
        data: visit,
      });
    } catch (error: any) {
      res.status(404).json({
        success: false,
        error: error.message,
      });
    }
  }

  async updateVisitStatus(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { status } = req.body;
      const visit = await visitService.updateVisitStatus(req.params.id, status);

      res.json({
        success: true,
        message: 'Visit status updated',
        data: visit,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async assignDoctor(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { doctorId } = req.body;
      const visit = await visitService.assignDoctor(req.params.id, doctorId);

      res.json({
        success: true,
        message: 'Doctor assigned successfully',
        data: visit,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async saveSoapNote(req: AuthRequest, res: Response): Promise<void> {
    try {
      const result = await visitService.saveSoapNote(
        req.params.id,
        req.user!.id,
        req.body
      );
      res.json({
        success: true,
        message: 'SOAP note saved successfully',
        data: result,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async getEncounterTimeline(req: AuthRequest, res: Response): Promise<void> {
    try {
      const timeline = await visitService.getEncounterTimeline(req.params.id);
      res.json({
        success: true,
        data: timeline,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async recordNurseVitals(req: AuthRequest, res: Response): Promise<void> {
    try {
      const result = await visitService.recordNurseVitals(
        req.params.id,
        req.user!.id,
        req.body
      );
      res.status(201).json({
        success: true,
        message: 'Vital signs recorded',
        data: result,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }
}
