import { Router } from 'express';
import * as ultrasoundController from '../controllers/ultrasound.controller';
import { authenticate, authorize } from '../middleware/auth';

const router = Router();

// All routes require authentication
router.use(authenticate);

// Create ultrasound order (doctors and receptionists)
router.post(
  '/',
  authorize('DOCTOR', 'RECEPTIONIST', 'SUPER_ADMIN'),
  ultrasoundController.createUltrasoundOrder
);

// Get ultrasound orders
router.get('/', ultrasoundController.getUltrasoundOrders);

// Get scheduled ultrasounds
router.get('/scheduled', ultrasoundController.getScheduledUltrasounds);

// Get ultrasound order by ID
router.get('/:id', ultrasoundController.getUltrasoundOrderById);

// Update ultrasound status
router.patch('/:id/status', ultrasoundController.updateUltrasoundStatus);

// Artifact lifecycle (metadata links)
router.get('/:id/artifacts', ultrasoundController.getUltrasoundArtifacts);
router.post('/:id/artifacts', ultrasoundController.addUltrasoundArtifact);

export default router;
