import prisma from '../config/database';
import { NotificationService } from './notification.service';
import { FinanceService } from './finance.service';
import { withDb } from '../utils/withDb';

const notificationService = new NotificationService();
const financeService = new FinanceService();

const VISIT_STATUSES = ['REGISTERED', 'IN_QUEUE', 'IN_CONSULTATION', 'COMPLETED'] as const;

async function assertDoctorUser(userId: string) {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: { id: true, role: true },
  });
  if (!user) {
    throw new Error('Doctor not found');
  }
  if (user.role !== 'DOCTOR' && user.role !== 'SUPER_ADMIN') {
    throw new Error('Assigned user must be a doctor');
  }
}

export class VisitService {
  async createVisit(data: {
    patientId: string;
    visitType: 'NEW' | 'REPEAT' | 'FOLLOW_UP';
    serviceType: 'OPD' | 'ULTRASOUND' | 'EMERGENCY' | 'INJECTION';
    assignedDoctorId?: string;
    registeredById: string;
    ultrasoundFee?: number;
  }) {
    const patient = await prisma.patient.findUnique({
      where: { id: data.patientId },
      select: { id: true },
    });
    if (!patient) {
      throw new Error('Patient not found');
    }

    if (data.assignedDoctorId) {
      await assertDoctorUser(data.assignedDoctorId);
    }

    // Get patient's last visit to determine card fee
    const lastVisit = await prisma.patientVisit.findFirst({
      where: { patientId: data.patientId },
      orderBy: { visitDate: 'desc' },
    });

    // Calculate card fee based on 30-day rule
    let cardFee = 30.00; // Default for new card
    if (lastVisit && data.visitType === 'REPEAT') {
      const daysSinceLastVisit = Math.floor(
        (Date.now() - lastVisit.visitDate.getTime()) / (1000 * 60 * 60 * 24)
      );
      
      // If within 30 days, card fee is 0
      if (daysSinceLastVisit <= 30) {
        cardFee = 0;
      }
    }

    // Get visit number for this patient
    const visitCount = await prisma.patientVisit.count({
      where: { patientId: data.patientId },
    });

    // Create visit
    const visit = await withDb(() =>
      prisma.patientVisit.create({
      data: {
        patientId: data.patientId,
        visitNumber: visitCount + 1,
        visitType: data.visitType,
        visitDate: new Date(),
        cardFee,
        serviceType: data.serviceType,
        assignedDoctorId: data.assignedDoctorId,
        status: 'REGISTERED',
        registeredById: data.registeredById,
      },
      include: {
        patient: {
          select: {
            id: true,
            cardNumber: true,
            fullName: true,
            sex: true,
            dateOfBirth: true,
            phone: true,
          },
        },
        assignedDoctor: {
          select: {
            id: true,
            fullName: true,
            department: true,
          },
        },
      },
    })
    );

    // Create financial transactions for card fee and service fee
    let totalRevenue = 0;

    if (Number(visit.cardFee) > 0) {
      await financeService.createPaidSystemCharge({
        patientId: visit.patientId,
        visitId: visit.id,
        transactionType: 'CARD_FEE',
        amount: Number(visit.cardFee),
        description: `Card fee for visit ${visit.visitNumber}`,
        collectedById: data.registeredById,
      });
      totalRevenue += Number(visit.cardFee);
    }

    // Handle ultrasound service fee
    if (data.serviceType === 'ULTRASOUND' && data.ultrasoundFee && data.ultrasoundFee > 0) {
      await financeService.createPaidSystemCharge({
        patientId: visit.patientId,
        visitId: visit.id,
        transactionType: 'ULTRASOUND_FEE',
        amount: data.ultrasoundFee,
        description: `Ultrasound service fee - ${data.visitType === 'FOLLOW_UP' ? 'Follow-up' : 'One-time'}`,
        collectedById: data.registeredById,
      });
      totalRevenue += data.ultrasoundFee;
    }

    return { ...visit, totalRevenue };
  }

  async getVisits(params: {
    page?: number;
    limit?: number;
    date?: string;
    status?: string;
    doctorId?: string;
    serviceType?: string;
    unassignedOnly?: boolean;
  }) {
    const page = params.page || 1;
    const limit = params.limit || 20;
    const skip = (page - 1) * limit;

    const where: any = {};

    if (params.date) {
      const startDate = new Date(params.date);
      const endDate = new Date(params.date);
      endDate.setHours(23, 59, 59, 999);
      
      where.visitDate = {
        gte: startDate,
        lte: endDate,
      };
    }

    if (params.status) {
      where.status = params.status;
    }

    if (params.doctorId) {
      where.assignedDoctorId = params.doctorId;
    }

    if (params.serviceType) {
      where.serviceType = params.serviceType;
    }

    if (params.unassignedOnly) {
      where.assignedDoctorId = null;
    }

    const [visits, total] = await Promise.all([
      prisma.patientVisit.findMany({
        where,
        skip,
        take: limit,
        orderBy: { visitDate: 'desc' },
        include: {
          patient: {
            select: {
              id: true,
              cardNumber: true,
              fullName: true,
              sex: true,
              dateOfBirth: true,
              photoUrl: true,
            },
          },
          assignedDoctor: {
            select: {
              fullName: true,
              department: true,
            },
          },
        },
      }),
      prisma.patientVisit.count({ where }),
    ]);

    // Get stats
    const stats = await prisma.patientVisit.groupBy({
      by: ['status'],
      where: params.date ? {
        visitDate: {
          gte: new Date(params.date),
          lte: new Date(new Date(params.date).setHours(23, 59, 59, 999)),
        },
      } : {},
      _count: true,
    });

    return {
      visits,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
      },
      stats: stats.reduce((acc, stat) => {
        acc[stat.status.toLowerCase()] = stat._count;
        return acc;
      }, {} as any),
    };
  }

  async getVisitById(id: string) {
    const visit = await prisma.patientVisit.findUnique({
      where: { id },
      include: {
        patient: true,
        assignedDoctor: {
          select: {
            fullName: true,
            department: true,
            phone: true,
          },
        },
        prescriptions: {
          include: {
            items: true,
          },
        },
        labOrders: {
          include: {
            items: true,
          },
        },
        ultrasoundOrders: true,
        injectionOrders: true,
        transactions: true,
      },
    });

    if (!visit) {
      throw new Error('Visit not found');
    }

    return visit;
  }

  async updateVisitStatus(id: string, status: string) {
    if (!VISIT_STATUSES.includes(status as (typeof VISIT_STATUSES)[number])) {
      throw new Error(`Invalid visit status: ${status}`);
    }

    return withDb(() =>
      prisma.patientVisit.update({
        where: { id },
        data: { status: status as any },
        include: {
          patient: {
            select: {
              fullName: true,
              cardNumber: true,
            },
          },
        },
      })
    );
  }

  async assignDoctor(visitId: string, doctorId: string) {
    await assertDoctorUser(doctorId);

    const visit = await withDb(() =>
      prisma.patientVisit.update({
        where: { id: visitId },
        data: {
          assignedDoctorId: doctorId,
          status: 'IN_QUEUE',
        },
        include: {
          patient: true,
          assignedDoctor: {
            select: {
              fullName: true,
              department: true,
            },
          },
        },
      })
    );

    // Notify doctor about new patient assignment
    // await notificationService.notifyNewPatient(doctorId, visit.patient.fullName, visit.id);

    return visit;
  }

  async saveSoapNote(
    visitId: string,
    authorId: string,
    payload: {
      patientId: string;
      chiefComplaint: string;
      subjective: string;
      objective: string;
      assessment: string;
      plan: string;
      vitalSigns?: {
        bloodPressure?: string;
        temperature?: string;
        heartRate?: string;
        respiratoryRate?: string;
        oxygenSaturation?: string;
      };
      isDraft?: boolean;
    }
  ) {
    const visit = await prisma.patientVisit.findUnique({ where: { id: visitId } });
    if (!visit) {
      throw new Error('Visit not found');
    }
    if (!payload.patientId || payload.patientId !== visit.patientId) {
      throw new Error('patientId does not match this visit');
    }
    if (payload.isDraft !== true) {
      const required = ['chiefComplaint', 'subjective', 'objective', 'assessment', 'plan'] as const;
      for (const key of required) {
        const v = payload[key];
        if (!v || !String(v).trim()) {
          throw new Error(`${key} is required`);
        }
      }
      if (String(payload.assessment).trim().length < 10) {
        throw new Error('assessment must be at least 10 characters');
      }
    }

    await prisma.auditLog.create({
      data: {
        userId: authorId,
        action: payload.isDraft ? 'SOAP_NOTE_DRAFT_SAVED' : 'SOAP_NOTE_SAVED',
        resource: 'patient_visits',
        resourceId: visitId,
        newValues: payload as any,
      },
    });

    return { visitId, saved: true };
  }

  async getEncounterTimeline(visitId: string) {
    const [visit, prescriptionRows, labRows, injectionRows, ultrasoundRows, txRows, logs] =
      await Promise.all([
        prisma.patientVisit.findUnique({
          where: { id: visitId },
          include: {
            registeredBy: { select: { fullName: true, role: true } },
            assignedDoctor: { select: { fullName: true, role: true } },
          },
        }),
        prisma.prescription.findMany({
          where: { visitId },
          select: { id: true, createdAt: true, status: true, doctor: { select: { fullName: true, role: true } } },
        }),
        prisma.labOrder.findMany({
          where: { visitId },
          select: { id: true, orderedAt: true, status: true, orderedBy: { select: { fullName: true, role: true } } },
        }),
        prisma.injectionOrder.findMany({
          where: { visitId },
          select: { id: true, createdAt: true, status: true, orderedBy: { select: { fullName: true, role: true } } },
        }),
        prisma.ultrasoundOrder.findMany({
          where: { visitId },
          select: { id: true, createdAt: true, status: true, orderedBy: { select: { fullName: true, role: true } } },
        }),
        prisma.financialTransaction.findMany({
          where: { visitId },
          select: {
            id: true,
            createdAt: true,
            transactionType: true,
            paymentStatus: true,
            collectedBy: { select: { fullName: true, role: true } },
          },
        }),
        prisma.auditLog.findMany({
          where: {
            OR: [{ resourceId: visitId }, { resource: 'patient_visits', resourceId: visitId }],
          },
          orderBy: { timestamp: 'desc' },
          include: { user: { select: { fullName: true, role: true } } },
          take: 100,
        }),
      ]);

    if (!visit) {
      throw new Error('Visit not found');
    }

    const synthesized = [
      {
        id: `visit-${visit.id}`,
        action: `VISIT_${visit.status}`,
        createdAt: visit.createdAt,
        resource: 'patient_visits',
        user: visit.registeredBy || null,
      },
      ...prescriptionRows.map((p) => ({
        id: `rx-${p.id}`,
        action: `PRESCRIPTION_${p.status}`,
        createdAt: p.createdAt,
        resource: 'prescriptions',
        user: p.doctor || null,
      })),
      ...labRows.map((l) => ({
        id: `lab-${l.id}`,
        action: `LAB_ORDER_${l.status}`,
        createdAt: l.orderedAt,
        resource: 'lab_orders',
        user: l.orderedBy || null,
      })),
      ...injectionRows.map((i) => ({
        id: `inj-${i.id}`,
        action: `INJECTION_ORDER_${i.status}`,
        createdAt: i.createdAt,
        resource: 'injection_orders',
        user: i.orderedBy || null,
      })),
      ...ultrasoundRows.map((u) => ({
        id: `us-${u.id}`,
        action: `ULTRASOUND_ORDER_${u.status}`,
        createdAt: u.createdAt,
        resource: 'ultrasound_orders',
        user: u.orderedBy || null,
      })),
      ...txRows.map((t) => ({
        id: `txn-${t.id}`,
        action: `${t.transactionType}_${t.paymentStatus}`,
        createdAt: t.createdAt,
        resource: 'financial_transactions',
        user: t.collectedBy || null,
      })),
    ];

    const merged = [...logs, ...synthesized]
      .sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
      .slice(0, 200);

    return merged;
  }

  async recordNurseVitals(
    visitId: string,
    userId: string,
    vitals: {
      bloodPressureSystolic: number;
      bloodPressureDiastolic: number;
      temperature: number;
      heartRate: number;
      respiratoryRate: number;
      oxygenSaturation: number;
      weight?: number;
      height?: number;
      bmi?: number;
      notes?: string;
    }
  ) {
    const visit = await prisma.patientVisit.findUnique({ where: { id: visitId } });
    if (!visit) {
      throw new Error('Visit not found');
    }
    const nums: Array<[string, number]> = [
      ['bloodPressureSystolic', vitals.bloodPressureSystolic],
      ['bloodPressureDiastolic', vitals.bloodPressureDiastolic],
      ['temperature', vitals.temperature],
      ['heartRate', vitals.heartRate],
      ['respiratoryRate', vitals.respiratoryRate],
      ['oxygenSaturation', vitals.oxygenSaturation],
    ];
    for (const [name, val] of nums) {
      if (!Number.isFinite(val)) {
        throw new Error(`${name} must be a valid number`);
      }
    }
    if (vitals.weight !== undefined && !Number.isFinite(vitals.weight)) {
      throw new Error('weight must be a valid number');
    }
    if (vitals.height !== undefined && !Number.isFinite(vitals.height)) {
      throw new Error('height must be a valid number');
    }
    if (vitals.bmi !== undefined && !Number.isFinite(vitals.bmi)) {
      throw new Error('bmi must be a valid number');
    }

    await prisma.auditLog.create({
      data: {
        userId,
        action: 'NURSE_VITALS_RECORDED',
        resource: 'patient_visits',
        resourceId: visitId,
        newValues: vitals as any,
      },
    });

    return { visitId, recorded: true };
  }
}
