import { Router } from 'express';
import { contactController } from '../controllers/contact.controller';
import { authenticate, authorize } from '../middleware/auth';

const router = Router();

// Public route - anyone can submit a contact message
router.post('/submit', contactController.submitMessage);

// Protected routes - only super admin can manage messages
router.get('/messages', authenticate, authorize(['SUPER_ADMIN']), contactController.getAllMessages);
router.get('/messages/:id', authenticate, authorize(['SUPER_ADMIN']), contactController.getMessageById);
router.patch('/messages/:id/respond', authenticate, authorize(['SUPER_ADMIN']), contactController.respondToMessage);
router.patch('/messages/:id/status', authenticate, authorize(['SUPER_ADMIN']), contactController.updateMessageStatus);
router.delete('/messages/:id', authenticate, authorize(['SUPER_ADMIN']), contactController.deleteMessage);

export default router;
