import { Request, Response } from 'express';
import { InjectionService } from '../services/injection.service';

const injectionService = new InjectionService();

export const createInjectionOrder = async (req: Request, res: Response) => {
  try {
    const order = await injectionService.createInjectionOrder({
      ...req.body,
      orderedById: req.user!.id,
    });

    res.status(201).json({
      success: true,
      data: order,
    });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      error: error.message || 'Failed to create injection order',
    });
  }
};

