import { Request, Response } from 'express';
import { contactService } from '../services/contact.service';

export const contactController = {
  // Submit a new contact message (public)
  async submitMessage(req: Request, res: Response) {
    try {
      const { fullName, email, phone, subject, message } = req.body;

      if (!fullName || !email || !message) {
        return res.status(400).json({
          success: false,
          error: 'Full name, email, and message are required',
        });
      }

      const contactMessage = await contactService.createMessage({
        fullName,
        email,
        phone,
        subject,
        message,
      });

      return res.status(201).json({
        success: true,
        message: 'Your message has been sent successfully. We will get back to you soon!',
        data: contactMessage,
      });
    } catch (error) {
      console.error('Error submitting contact message:', error);
      return res.status(500).json({
        success: false,
        error: 'Failed to submit message. Please try again later.',
      });
    }
  },

  // Get all contact messages (admin only)
  async getAllMessages(req: Request, res: Response) {
    try {
      const { status, page = '1', limit = '20' } = req.query;

      const messages = await contactService.getAllMessages({
        status: status as string,
        page: parseInt(page as string),
        limit: parseInt(limit as string),
      });

      return res.status(200).json({
        success: true,
        data: messages,
      });
    } catch (error) {
      console.error('Error fetching contact messages:', error);
      return res.status(500).json({
        success: false,
        error: 'Failed to fetch messages',
      });
    }
  },

  // Get a single message by ID (admin only)
  async getMessageById(req: Request, res: Response) {
    try {
      const { id } = req.params;

      const message = await contactService.getMessageById(id);

      if (!message) {
        return res.status(404).json({
          success: false,
          error: 'Message not found',
        });
      }

      return res.status(200).json({
        success: true,
        data: message,
      });
    } catch (error) {
      console.error('Error fetching message:', error);
      return res.status(500).json({
        success: false,
        error: 'Failed to fetch message',
      });
    }
  },

  // Respond to a message (admin only)
  async respondToMessage(req: Request, res: Response) {
    try {
      const { id } = req.params;
      const { response } = req.body;
      const userId = req.user?.id;

      if (!response) {
        return res.status(400).json({
          success: false,
          error: 'Response text is required',
        });
      }

      const updatedMessage = await contactService.respondToMessage(id, response, userId!);

      return res.status(200).json({
        success: true,
        message: 'Response sent successfully',
        data: updatedMessage,
      });
    } catch (error) {
      console.error('Error responding to message:', error);
      return res.status(500).json({
        success: false,
        error: 'Failed to send response',
      });
    }
  },

  // Update message status (admin only)
  async updateMessageStatus(req: Request, res: Response) {
    try {
      const { id } = req.params;
      const { status } = req.body;

      if (!status) {
        return res.status(400).json({
          success: false,
          error: 'Status is required',
        });
      }

      const updatedMessage = await contactService.updateMessageStatus(id, status);

      return res.status(200).json({
        success: true,
        message: 'Status updated successfully',
        data: updatedMessage,
      });
    } catch (error) {
      console.error('Error updating message status:', error);
      return res.status(500).json({
        success: false,
        error: 'Failed to update status',
      });
    }
  },

  // Delete a message (admin only)
  async deleteMessage(req: Request, res: Response) {
    try {
      const { id } = req.params;

      await contactService.deleteMessage(id);

      return res.status(200).json({
        success: true,
        message: 'Message deleted successfully',
      });
    } catch (error) {
      console.error('Error deleting message:', error);
      return res.status(500).json({
        success: false,
        error: 'Failed to delete message',
      });
    }
  },
};
