import { Response } from 'express';
import { AuthRequest } from '../middleware/auth';
import { UserService } from '../services/user.service';

const userService = new UserService();

export const getMyProfile = async (req: AuthRequest, res: Response) => {
  try {
    const profile = await userService.getProfile(req.user!.id);
    res.json({ success: true, data: profile });
  } catch (error: any) {
    res.status(500).json({
      success: false,
      error: error.message || 'Failed to fetch profile',
    });
  }
};

export const updateMyProfile = async (req: AuthRequest, res: Response) => {
  try {
    const { fullName, phone, department } = req.body;
    const profile = await userService.updateProfile(req.user!.id, {
      fullName,
      phone,
      department,
    });
    res.json({
      success: true,
      data: profile,
      message: 'Profile updated successfully',
    });
  } catch (error: any) {
    res.status(400).json({
      success: false,
      error: error.message || 'Failed to update profile',
    });
  }
};

export const changePassword = async (req: AuthRequest, res: Response) => {
  try {
    const { currentPassword, newPassword } = req.body;
    
    if (!currentPassword || !newPassword) {
      res.status(400).json({
        success: false,
        error: 'Current password and new password are required',
      });
      return;
    }

    if (newPassword.length < 6) {
      res.status(400).json({
        success: false,
        error: 'New password must be at least 6 characters',
      });
      return;
    }

    await userService.changePassword(req.user!.id, currentPassword, newPassword);
    
    res.json({
      success: true,
      message: 'Password changed successfully',
    });
  } catch (error: any) {
    res.status(400).json({
      success: false,
      error: error.message || 'Failed to change password',
    });
  }
};

export const requestEmailChange = async (req: AuthRequest, res: Response) => {
  try {
    const { newEmail, password } = req.body;
    
    console.log(`[requestEmailChange] User ${req.user!.id} requesting email change to ${newEmail}`);
    
    if (!newEmail || !password) {
      res.status(400).json({
        success: false,
        error: 'New email and password are required',
      });
      return;
    }

    await userService.requestEmailChange(req.user!.id, newEmail, password);
    
    console.log(`[requestEmailChange] ✅ OTP sent successfully to ${newEmail}`);
    
    res.json({
      success: true,
      message: 'OTP sent to your new email address',
    });
  } catch (error: any) {
    console.error(`[requestEmailChange] ❌ Error:`, error.message);
    res.status(400).json({
      success: false,
      error: error.message || 'Failed to request email change',
    });
  }
};

export const confirmEmailChange = async (req: AuthRequest, res: Response) => {
  try {
    const { otp } = req.body;
    
    console.log(`[confirmEmailChange] User ${req.user!.id} verifying OTP: ${otp}`);
    
    if (!otp) {
      res.status(400).json({
        success: false,
        error: 'OTP code is required',
      });
      return;
    }

    const result = await userService.confirmEmailChange(req.user!.id, otp);
    
    console.log(`[confirmEmailChange] ✅ Email changed successfully to ${result.email}`);
    
    res.json({
      success: true,
      data: result,
      message: 'Email changed successfully',
    });
  } catch (error: any) {
    console.error(`[confirmEmailChange] ❌ Error:`, error.message);
    res.status(400).json({
      success: false,
      error: error.message || 'Failed to confirm email change',
    });
  }
};

export const uploadProfilePhoto = async (req: AuthRequest, res: Response) => {
  try {
    if (!req.file) {
      res.status(400).json({
        success: false,
        error: 'No file uploaded',
      });
      return;
    }

    const photoUrl = await userService.uploadProfilePhoto(req.user!.id, req.file);
    
    res.json({
      success: true,
      data: { photoUrl },
      message: 'Profile photo uploaded successfully',
    });
  } catch (error: any) {
    res.status(400).json({
      success: false,
      error: error.message || 'Failed to upload photo',
    });
  }
};

export const deleteProfilePhoto = async (req: AuthRequest, res: Response) => {
  try {
    await userService.deleteProfilePhoto(req.user!.id);
    
    res.json({
      success: true,
      message: 'Profile photo deleted successfully',
    });
  } catch (error: any) {
    res.status(400).json({
      success: false,
      error: error.message || 'Failed to delete photo',
    });
  }
};
