import { Request, Response } from 'express';
import { AuthService } from '../services/auth.service';
import { AuthRequest } from '../middleware/auth';

const authService = new AuthService();

export class AuthController {
  async register(req: Request, res: Response): Promise<void> {
    try {
      const user = await authService.register(req.body);

      res.status(201).json({
        success: true,
        message: 'Registration submitted for approval',
        data: user,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async registerPatient(req: Request, res: Response): Promise<void> {
    try {
      const user = await authService.registerPatientPortal(req.body);
      res.status(201).json({
        success: true,
        message: 'Patient portal account created. You can sign in now.',
        data: user,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async login(req: Request, res: Response): Promise<void> {
    try {
      const { email, password, otp } = req.body;
      const result = await authService.login(email, password, otp);

      res.json({
        success: true,
        data: result,
      });
    } catch (error: any) {
      // Special handling for first login OTP required
      if (error.message === 'FIRST_LOGIN_OTP_REQUIRED') {
        res.status(403).json({
          success: false,
          error: 'First login OTP required',
          errorCode: 'OTP_REQUIRED',
          requiresOTP: true,
        });
        return;
      }

      res.status(401).json({
        success: false,
        error: error.message,
        errorCode: 'AUTH_FAILED'
      });
    }
  }

  async logout(req: AuthRequest, res: Response): Promise<void> {
    try {
      const token = req.headers.authorization?.split(' ')[1];
      if (token) {
        await authService.logout(token);
      }

      res.json({
        success: true,
        message: 'Logged out successfully',
      });
    } catch (error: any) {
      res.status(500).json({
        success: false,
        error: error.message,
      });
    }
  }

  async me(req: AuthRequest, res: Response): Promise<void> {
    try {
      const user = await authService.getCurrentUser(req.user.id);

      res.json({
        success: true,
        data: user,
      });
    } catch (error: any) {
      res.status(404).json({
        success: false,
        error: error.message,
      });
    }
  }

  async verifyEmail(req: Request, res: Response): Promise<void> {
    try {
      const token = String(req.query.token || '').trim();
      if (!token) {
        res.status(400).json({
          success: false,
          error: 'Verification token is required',
        });
        return;
      }

      const user = await authService.verifyEmail(token);
      res.json({
        success: true,
        message: 'Email verified successfully',
        data: user,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async getDoctors(_req: AuthRequest, res: Response): Promise<void> {
    try {
      const doctors = await authService.getDoctors();
      res.json({
        success: true,
        data: doctors,
      });
    } catch (error: any) {
      res.status(500).json({
        success: false,
        error: error.message,
      });
    }
  }

  async switchToClinical(req: AuthRequest, res: Response): Promise<void> {
    try {
      const result = await authService.switchToClinicalPersona(req.user!.id);
      res.json({ success: true, data: result });
    } catch (error: any) {
      res.status(400).json({ success: false, error: error.message });
    }
  }

  async switchToAdmin(req: AuthRequest, res: Response): Promise<void> {
    try {
      const result = await authService.switchToAdminPersona(req.user!.id);
      res.json({ success: true, data: result });
    } catch (error: any) {
      res.status(400).json({ success: false, error: error.message });
    }
  }
}
