import { Router } from 'express';
import * as pharmacyController from '../controllers/pharmacy.controller';
import { authenticate, authorize } from '../middleware/auth';

const router = Router();

// All routes require authentication
router.use(authenticate);

// Drug Management
router.post(
  '/drugs',
  authorize('PHARMACIST', 'SUPER_ADMIN'),
  pharmacyController.createDrug
);

router.get('/drugs', pharmacyController.getDrugs);

// Stock Management
router.post(
  '/stock',
  authorize('PHARMACIST', 'SUPER_ADMIN'),
  pharmacyController.addStock
);

router.get('/stock', pharmacyController.getStock);

router.get(
  '/stock/alerts',
  authorize('PHARMACIST', 'SUPER_ADMIN'),
  pharmacyController.getLowStockAlerts
);

router.get(
  '/stock/expiring',
  authorize('PHARMACIST', 'SUPER_ADMIN'),
  pharmacyController.getExpiringStock
);

router.get('/stock/:id', pharmacyController.getStockById);

router.patch(
  '/stock/:id',
  authorize('PHARMACIST', 'SUPER_ADMIN'),
  pharmacyController.updateStock
);

// Dispensing
router.post(
  '/dispense',
  authorize('PHARMACIST', 'SUPER_ADMIN'),
  pharmacyController.dispenseStock
);

export default router;
