import { Router } from 'express';
import * as financeController from '../controllers/finance.controller';
import { authenticate, authorize } from '../middleware/auth';

const router = Router();

// All routes require authentication
router.use(authenticate);

// Transactions
router.post(
  '/transactions',
  authorize('RECEPTIONIST', 'FINANCE', 'SUPER_ADMIN'),
  financeController.createTransaction
);

router.get(
  '/transactions',
  authorize('FINANCE', 'SUPER_ADMIN'),
  financeController.getTransactions
);
router.patch(
  '/transactions/:id/pay',
  authorize('FINANCE', 'SUPER_ADMIN'),
  financeController.markTransactionPaid
);
router.post(
  '/transactions/:id/refund-request',
  authorize('FINANCE', 'SUPER_ADMIN'),
  financeController.requestRefund
);
router.post(
  '/transactions/:id/refund-approve',
  authorize('SUPER_ADMIN'),
  financeController.approveRefund
);

// Invoices
router.post(
  '/invoices',
  authorize('RECEPTIONIST', 'FINANCE', 'SUPER_ADMIN'),
  financeController.createInvoice
);

router.get(
  '/invoices',
  authorize('FINANCE', 'SUPER_ADMIN'),
  financeController.getInvoices
);

router.post(
  '/invoices/:id/pay',
  authorize('RECEPTIONIST', 'FINANCE', 'SUPER_ADMIN'),
  financeController.payInvoice
);

// Reports
router.get(
  '/reports/revenue',
  authorize('FINANCE', 'SUPER_ADMIN'),
  financeController.getRevenueReport
);

router.get(
  '/reports/daily',
  authorize('RECEPTIONIST', 'FINANCE', 'PHARMACIST', 'SUPER_ADMIN'),
  financeController.getDailyRevenue
);
router.get(
  '/closeout/daily',
  authorize('FINANCE', 'SUPER_ADMIN'),
  financeController.getDailyCloseoutSummary
);

export default router;
