import { Response } from 'express';
import { PrescriptionService } from '../services/prescription.service';
import { AuthRequest } from '../middleware/auth';

const prescriptionService = new PrescriptionService();

export class PrescriptionController {
  async createPrescription(req: AuthRequest, res: Response): Promise<void> {
    try {
      const prescription = await prescriptionService.createPrescription({
        ...req.body,
        doctorId: req.user!.id,
      });

      res.status(201).json({
        success: true,
        message: 'Prescription created successfully',
        data: prescription,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async getPrescriptions(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { page, limit, status, patientId, doctorId, date } = req.query;

      const result = await prescriptionService.getPrescriptions({
        page: page ? Number(page) : undefined,
        limit: limit ? Number(limit) : undefined,
        status: status as string,
        patientId: patientId as string,
        doctorId: doctorId as string,
        date: date as string,
      });

      res.json({
        success: true,
        data: result,
      });
    } catch (error: any) {
      res.status(500).json({
        success: false,
        error: error.message,
      });
    }
  }

  async getPrescriptionById(req: AuthRequest, res: Response): Promise<void> {
    try {
      const prescription = await prescriptionService.getPrescriptionById(req.params.id);

      res.json({
        success: true,
        data: prescription,
      });
    } catch (error: any) {
      res.status(404).json({
        success: false,
        error: error.message,
      });
    }
  }

  async dispensePrescription(req: AuthRequest, res: Response): Promise<void> {
    try {
      const prescription = await prescriptionService.dispensePrescription(
        req.params.id,
        req.user!.id,
        {
          labelPrinted: Boolean(req.body?.labelPrinted),
          substitutionMade: Boolean(req.body?.substitutionMade),
          substitutionReason: req.body?.substitutionReason,
          counselProvided: Boolean(req.body?.counselProvided),
          notes: req.body?.notes,
        }
      );

      res.json({
        success: true,
        message: 'Prescription dispensed successfully',
        data: prescription,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async cancelPrescription(req: AuthRequest, res: Response): Promise<void> {
    try {
      const prescription = await prescriptionService.cancelPrescription(req.params.id);

      res.json({
        success: true,
        message: 'Prescription cancelled',
        data: prescription,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async getPrescriptionQueue(req: AuthRequest, res: Response): Promise<void> {
    try {
      const limit = req.query.limit ? Number(req.query.limit) : undefined;
      const prescriptions = await prescriptionService.getPrescriptionQueue({
        limit: Number.isFinite(limit) ? limit : undefined,
      });

      res.json({
        success: true,
        data: prescriptions,
      });
    } catch (error: any) {
      res.status(500).json({
        success: false,
        error: error.message,
      });
    }
  }
}
