import { Router } from 'express';
import { PrismaClient } from '@prisma/client';
import { authenticate } from '../middleware/auth';

const router = Router();
const prisma = new PrismaClient();

// Get all lab tests
router.get('/tests', authenticate, async (req, res) => {
  try {
    const tests = await prisma.labTest.findMany({
      where: {
        isActive: true
      },
      select: {
        id: true,
        testName: true,
        testCategory: true,
        price: true,
      },
      orderBy: {
        testCategory: 'asc'
      }
    });

    // Map to frontend format
    const formattedTests = tests.map(test => ({
      id: test.id,
      name: test.testName,
      category: test.testCategory || 'Other',
      price: test.price ? Number(test.price) : 0
    }));

    res.json({
      success: true,
      data: formattedTests
    });
  } catch (error: any) {
    console.error('Error fetching lab tests:', error);
    res.status(500).json({
      success: false,
      error: 'Failed to fetch lab tests'
    });
  }
});

// Get lab orders (for lab queue)
router.get('/orders', authenticate, async (req, res) => {
  try {
    const { status, limit } = req.query;
    
    const whereClause: any = {};
    if (status) {
      whereClause.status = status;
    }
    
    const orders = await prisma.labOrder.findMany({
      where: whereClause,
      take: limit ? parseInt(limit as string) : 50,
      orderBy: {
        orderedAt: 'desc'
      },
      include: {
        patient: {
          select: {
            id: true,
            cardNumber: true,
            fullName: true,
            sex: true,
            dateOfBirth: true,
          }
        },
        orderedBy: {
          select: {
            fullName: true,
          }
        },
        items: {
          include: {
            test: true,
          }
        }
      }
    });

    // Map to frontend format
    const formattedOrders = orders.map((order: any) => ({
      id: order.id,
      orderNumber: order.orderNumber,
      orderedAt: order.orderedAt.toISOString(),
      status: order.status,
      urgency: order.priority,
      patient: {
        id: order.patient.id,
        cardNumber: order.patient.cardNumber,
        fullName: order.patient.fullName,
        sex: order.patient.sex,
        dateOfBirth: order.patient.dateOfBirth.toISOString(),
      },
      orderedBy: order.orderedBy,
      items: order.items.map((item: any) => ({
        id: item.id,
        testName: item.testName,
        status: item.status,
        result: item.result,
        isAbnormal: item.isAbnormal,
      }))
    }));

    res.json({
      success: true,
      data: formattedOrders
    });
  } catch (error: any) {
    console.error('Error fetching lab orders:', error);
    res.status(500).json({
      success: false,
      error: 'Failed to fetch lab orders'
    });
  }
});

// Add result to lab order item
router.post('/orders/:orderId/results', authenticate, async (req, res) => {
  try {
    const { orderId } = req.params;
    const { itemId, result, isAbnormal } = req.body;

    await prisma.labOrderItem.update({
      where: { id: itemId },
      data: {
        result,
        isAbnormal: isAbnormal || false,
        status: 'COMPLETED',
      }
    });

    res.json({
      success: true,
      message: 'Result added successfully'
    });
  } catch (error: any) {
    console.error('Error adding lab result:', error);
    res.status(500).json({
      success: false,
      error: 'Failed to add result'
    });
  }
});

// Update lab order status
router.patch('/orders/:orderId/status', authenticate, async (req, res) => {
  try {
    const { orderId } = req.params;
    const { status } = req.body;

    await prisma.labOrder.update({
      where: { id: orderId },
      data: {
        status,
        completedAt: status === 'COMPLETED' ? new Date() : undefined,
        verifiedAt: status === 'VERIFIED' ? new Date() : undefined,
        verifiedById: status === 'VERIFIED' ? req.user?.id : undefined,
      }
    });

    res.json({
      success: true,
      message: 'Status updated successfully'
    });
  } catch (error: any) {
    console.error('Error updating lab order status:', error);
    res.status(500).json({
      success: false,
      error: 'Failed to update status'
    });
  }
});

export default router;
