import { Response } from 'express';
import { AppointmentService } from '../services/appointment.service';
import { AuthRequest } from '../middleware/auth';

const appointmentService = new AppointmentService();

export class AppointmentController {
  async createAppointment(req: AuthRequest, res: Response): Promise<void> {
    try {
      const appointment = await appointmentService.createAppointment(req.body);

      res.status(201).json({
        success: true,
        message: 'Appointment created successfully',
        data: appointment,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async getAppointments(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { doctorId, patientId, status, date, page, limit } = req.query;

      const result = await appointmentService.getAppointments({
        doctorId: doctorId as string,
        patientId: patientId as string,
        status: status as any,
        date: date as string,
        page: page ? Number(page) : undefined,
        limit: limit ? Number(limit) : undefined,
      });

      res.json({
        success: true,
        data: result,
      });
    } catch (error: any) {
      res.status(500).json({
        success: false,
        error: error.message,
      });
    }
  }

  async getAppointmentById(req: AuthRequest, res: Response): Promise<void> {
    try {
      const appointment = await appointmentService.getAppointmentById(req.params.id);

      res.json({
        success: true,
        data: appointment,
      });
    } catch (error: any) {
      res.status(404).json({
        success: false,
        error: error.message,
      });
    }
  }

  async checkInAppointment(req: AuthRequest, res: Response): Promise<void> {
    try {
      const result = await appointmentService.checkInAppointment(
        req.params.id,
        req.user.id
      );

      res.json({
        success: true,
        message: 'Appointment checked in successfully',
        data: result,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async cancelAppointment(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { reason } = req.body;

      if (!reason || !reason.trim()) {
        res.status(400).json({
          success: false,
          error: 'Cancellation reason is required',
        });
        return;
      }

      const appointment = await appointmentService.cancelAppointment(
        req.params.id,
        reason,
        req.user.id
      );

      res.json({
        success: true,
        message: 'Appointment cancelled successfully',
        data: appointment,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async rescheduleAppointment(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { appointmentDate, startTime, endTime } = req.body;

      if (!appointmentDate || !startTime || !endTime) {
        res.status(400).json({
          success: false,
          error: 'appointmentDate, startTime, and endTime are required',
        });
        return;
      }

      const appointment = await appointmentService.rescheduleAppointment(
        req.params.id,
        new Date(appointmentDate),
        new Date(startTime),
        new Date(endTime)
      );

      res.json({
        success: true,
        message: 'Appointment rescheduled successfully',
        data: appointment,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async markNoShow(req: AuthRequest, res: Response): Promise<void> {
    try {
      const appointment = await appointmentService.markNoShow(req.params.id);

      res.json({
        success: true,
        message: 'Appointment marked as no-show',
        data: appointment,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }

  async uncheckInAppointment(req: AuthRequest, res: Response): Promise<void> {
    try {
      const appointment = await appointmentService.uncheckInAppointment(req.params.id);

      res.json({
        success: true,
        message: 'Appointment unchecked-in successfully',
        data: appointment,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        error: error.message,
      });
    }
  }
}
