import { Response } from 'express';
import { AuthRequest } from '../middleware/auth';
import { certificateService } from '../services/certificate.service';

export class CertificateController {
  // ============================================
  // SICK LEAVE CERTIFICATES
  // ============================================

  async createSickLeaveCertificate(req: AuthRequest, res: Response): Promise<void> {
    try {
      const certificateData = {
        ...req.body,
        issuedById: req.user!.id,
      };

      const certificate = await certificateService.createSickLeaveCertificate(certificateData);

      res.status(201).json({
        success: true,
        data: certificate,
        message: 'Sick leave certificate created successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getSickLeaveCertificate(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const certificate = await certificateService.getSickLeaveCertificate(id);

      if (!certificate) {
        res.status(404).json({
          success: false,
          message: 'Sick leave certificate not found',
        });
        return;
      }

      res.json({
        success: true,
        data: certificate,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getPatientSickLeaveCertificates(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { patientId } = req.params;
      const certificates = await certificateService.getPatientSickLeaveCertificates(patientId);

      res.json({
        success: true,
        data: certificates,
        count: certificates.length,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  // ============================================
  // MEDICAL CERTIFICATES
  // ============================================

  async createMedicalCertificate(req: AuthRequest, res: Response): Promise<void> {
    try {
      const certificateData = {
        ...req.body,
        issuedById: req.user!.id,
      };

      const certificate = await certificateService.createMedicalCertificate(certificateData);

      res.status(201).json({
        success: true,
        data: certificate,
        message: 'Medical certificate created successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async updateMedicalCertificate(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const certificate = await certificateService.updateMedicalCertificate(id, req.body);

      res.json({
        success: true,
        data: certificate,
        message: 'Medical certificate updated successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async signMedicalCertificate(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const certificate = await certificateService.signMedicalCertificate(id, req.body);

      res.json({
        success: true,
        data: certificate,
        message: 'Medical certificate signed successfully',
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getMedicalCertificate(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { id } = req.params;
      const certificate = await certificateService.getMedicalCertificate(id);

      if (!certificate) {
        res.status(404).json({
          success: false,
          message: 'Medical certificate not found',
        });
        return;
      }

      res.json({
        success: true,
        data: certificate,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }

  async getPatientMedicalCertificates(req: AuthRequest, res: Response): Promise<void> {
    try {
      const { patientId } = req.params;
      const certificates = await certificateService.getPatientMedicalCertificates(patientId);

      res.json({
        success: true,
        data: certificates,
        count: certificates.length,
      });
    } catch (error: any) {
      res.status(400).json({
        success: false,
        message: error.message,
      });
    }
  }
}

export const certificateController = new CertificateController();
